      "pts": 2,
      "title": "프로이덴탈이 비판한 교수학적 접근 방식의 명칭",
      "problem": "프로이덴탈(H. Freudenthal)의 수학화 교수·학습 이론에 따르면, 아래의 2가지 사항은 현상으로부터 본질에 이르는 접근이 아니라 학습자에게 본질을 부과하는 접근이다. 프로이덴탈은 이와 같은 교수학적 접근 방식을 무엇이라 하였는지 쓰시오. [2점]\n\n○ 기성 수학의 전개 순서에 따라 학교수학의 교재를 구성하는 것\n○ 수학화 과정에 대한 경험은 생략하고 기성 지식을 초등화해 가르치는 것",
