          "body": "제시된 두 사항은 모두 현상에서 출발하지 않고, 이미 완성된 형태의 수학(기성 수학)을 학생에게 그대로 부과하는 접근이다. 이는 학생이 수학화 과정을 스스로 경험하도록 안내하는 것이 아니라, 완성된 결과물을 전달하는 방식이다."
