      "answer": "프로이덴탈이 말하는 반교수학적 전도(anti-didactical inversion)는, 수학자가 실제로 개념을 발견한 순서(현상에서 본질로 나아가는 순서)와 그것을 논리적으로 재구성하여 가르치는 순서가 뒤바뀌어, 학습자에게 완성된 최종 결과(기성 수학)를 처음부터 부과하는 현상을 가리킨다.\n\n제시된 두 사항, 즉 \"기성 수학의 전개 순서에 따라 교재를 구성하는 것\"과 \"수학화 과정에 대한 경험은 생략하고 기성 지식을 초등화해 가르치는 것\"은 모두 학생이 스스로 수학을 발생시키는 과정을 경험하지 못한 채 완성된 지식을 그대로 받아들이게 한다는 점에서, 프로이덴탈이 말한 반교수학적 전도에 해당한다.",
