      "problem": "다음은 중학교 2학년 기하 영역의 평행사변형의 성질을 다루는 수업의 일부이다.\n\n교사: 측정 활동을 통해 알아낸 평행사변형의 성질 '두 쌍의 대각의 크기가 각각 같다.'가 왜 성립하는지 설명해 보도록 하지요.\n학생: 어려워요.\n(이 문제를 해결한 학생이 없는 듯 보인다.)\n교사: 시간이 없으니 어쩔 수 없네요. 대각선을 그어 평행사변형을 두 삼각형으로 나누면, 그 두 삼각형이 합동이 돼요. 그러면 그 성질이 성립한다는 것을 바로 보일 수 있을 것입니다.\n학생: 합동이 되니까 성립하네요.\n교사: 그러면 다음 내용을 공부합시다.\n\n밑줄 친 부분에서 학생 스스로 학습할 환경을 교사가 제거하는 현상이 발생하고 있다. 여기서 이 교수학적 현상은 '교사는 수학적 지식을 가르쳐야 하고 학생은 그것을 배워야 한다.'는 압박에 의해 발생한다고 할 수 있다. 브루소(G. Brousseau)의 수학 교수학적 상황론(Theory of Didactical Situations in Mathematics)에서 이러한 현상을 설명할 수 있는 개념과 이러한 압박을 설명할 수 있는 개념을 각각 쓰시오. [2점]",
