      "answer": "제시된 문제해결 과정에는 수학적 발견술인 분석법(analysis)이 사용되고 있다. 분석법이란 구하려는 결론을 먼저 참이라고 가정한 뒤, 그 가정으로부터 논리적으로 필연적인 관계를 역으로 추적하여 이미 알려진 사실이나 풀 수 있는 형태에 도달하는 발견적 방법이다.\n\n계획 단계에서는 \"주어진 방정식이 참이라고 하자\"라고 결론(가정)을 먼저 설정한 후, 그 가정으로부터 필요한 조건(방정식)을 역방향으로 도출하고 있다. 이는 구하려는 것을 참이라 가정하고 그로부터 필연적으로 따르는 관계를 찾는 분석법의 전형적 절차이다.\n\n실행 단계에서는 계획 단계에서 세운 방정식을 참이라 가정한 상태에서 양변을 제곱하는 등 논리적 조작을 통해 필요조건($x=3$ 또는 $x=5$)을 이끌어낸다. 이때 유도된 것은 필요조건일 뿐 충분조건이 보장되지 않으므로, 그 역방향의 타당성은 반성 단계에서 별도로 검증해야 함을 보여준다.",
