      "problem": "중학교 기하 수업에서 다음과 같은 자료를 이용하여 정사면체에 대해 학습하였다.\n\n<빨대로 만든 정사면체> <종이로 만든 정사면체> <자석막대로 만든 정사면체> <정사면체 모양의 지갑>\n\n위 자료들은 서로 다르게 보이지만, 구조적으로는 같은 구체물이다. 딘즈(Z. Dienes)의 수학 학습 이론에서 볼 때, 이러한 다양한 형태의 구체물을 활용한 수업은 어떤 원리를 적용한 것인지 쓰시오. [2점]",
