      "title": "라카토스의 준경험주의 관점에서 반례 대응 방법과 수학적 지식의 성장",
      "problem": "다음은 박 교수가 수학 교육론 강의 시간에 라카토스(I. Lakatos)의 준경험주의를 주제로 진행한 강의의 일부이다.\n\n박 교수: 하나의 추측을 제기하고, 그 추측을 부분추측으로 분해하는 1가지 사례를 발표해 봅시다.\n민 태: 방정식 $ax^{2}+bx+c=0$은 두 실근을 가진다는 추측을 제기하고, 세 단계로 분해하여 보았습니다.\n[1단계: $f(x)=ax^{2}+bx+c$의 그래프는 포물선이고, 실근의 개수는 그래프가 x축과 만나는 점의 개수와 같습니다.]\n[2단계: 그래프의 꼭짓점 (p,q)는 $(-b$/2a, $-(b^{2}-4ac)$/4a)인데, a의 부호를 기준으로 생각하면, a>0일 때 p<0, q<0이고 a<0일 때 p>0, q>0입니다.]\n[3단계: 포물선의 모양을 생각하면, a>0일 때 꼭짓점이 제3사분면, a<0일 때 꼭짓점이 제1사분면에 있으므로 그래프가 x축과 만나는 점은 2개입니다.]\n박 교수: 민태가 제기한 추측을 통해 라카토스의 준경험주의의 관점에서 수업을 진행해 봅시다.\n혜 수: 교수님, ㉠방정식 $x^{2}-4x+4=0$은 근이 $x=2$이고, 하나의 실근만을 가집니다.\n학생들: 맞아요. 민태의 처음 추측이 틀렸어요.\n현 덕: 저는 다르게 생각합니다. ㉡어떤 추측이 항상 참이 된다고는 생각하지 않습니다. 그러나 지금 이 경우에는 혜수가 발한 것을 예외로 인정하면 민태의 추측을 옹호할 수 있습니다.\n박 교수: 어디 한번 봅시다. 만약 혜수의 말이 옳다면, 민태의 부분추측은 어디가 잘못되었을까요?\n혜 수: 2단계가 잘못된 것 같아요. a>0일 때 b의 값을 함께 고려해 보겠습니다. 만약 $b=0$이면 p<0이 아니라 $p=-b$/$2a=0$이 됩니다.\n박 교수: 그렇군요. 그러면 부분추측을 수정해야겠군요. ...\n\n위 상황에서 ㉡의 관점에서 ㉠과 같은 반례가 출현할 때, 이 반례에 대한 라카토스의 대응 방법을 무엇이라고 부르는지 적고, 이러한 대응 방법으로 인해 발생할 수 있는 현상에 대해 쓰시오. 또, 위 강의 내용을 참고하여 라카토스의 준경험주의 관점에서 수학적 지식의 성장 과정을 설명하시오. [5점]",
