      "title": "수업참관일지에서 나타난 귀납적 추론 유형과 시각적 모형의 필요성",
      "problem": "다음은 김 교사가 정 교사의 수업을 참관한 후, 김 교사가 작성한 수업참관일지와 정 교사가 작성한 수업소감문의 일부이다.\n\n(가) 김 교사의 수업참관일지: 정 교사는 도입 단계에서 $1+3+5+7=16=4^{2}$ 같은 사실을 제시하여 학습 동기를 유발하고자 하였다. \"연속한 홀수의 합은 어떤 수의 제곱이 될까?\"라고 발문하며, $1+3+5+$⋯$+(2n-1)=$[ ]$^{2}$ 이라는 탐구과제를 제시하였다. 학생들은 $1=1=1^{2}$, $1+3=4=2^{2}$, $1+3+5=9=3^{2}$, $1+3+5+7=16=4^{2}$, $1+3+5+7+9=25=5^{2}$ 같은 특수한 사례를 조사하였다. 학생들은 구체적인 사례에 대한 관찰로부터 새로운 추측 $1+3+5+$⋯$+(2n-1)=n^{2}$ 을 발견하였다. 이러한 발견 이후, ㉠정 교사는 수학적 귀납법을 이용하여 탐구과제에 대한 수업을 계속 진행하였다.\n\n(나) 정 교사의 수업소감문: 학생들은 자신들이 관찰한 구체적인 사례로부터 공통점에 주목하여 새로운 추측을 잘 이끌어 내었다. 하지만, 조금 아쉬운 점은 ㉡$1+3+5+$⋯$+(2n-1)=n^{2}$이 성립함을 보여 주는 시각적 모형(visual model)을 학생들에게 제공해 주지 못했다는 것이다.\n\n위의 수업참관일지를 통해 볼 때, 정 교사의 수업에서 학생들이 사용했을 추론 유형을 적고, 이 추론 유형의 특성에 근거하여 ㉠의 이유를 설명하시오. 또, 수업소감문에 제시된 ㉡에 해당하는 구체적인 예를 하나 제시하시오. [5점]",
