      "problem": "2009 개정 교육과정에 따른 수학과 교육과정의 중학교 수와 연산 영역 <교수·학습상의 유의점>에 '유한소수를 순환소수로 나타내는 것은 다루지 않는다'고 명시되어 있다. 이 유의점이 명시되어 있는 이유를 구체적인 사례와 함께 쓰시오. 또, <보기>와 같이 순환소수를 분수로 고치는 학습 내용을 지도할 때, 유의해야 할 점을 교육과정에 근거하여 서술하시오. [5점]\n\n<보기> 순환소수 0.7̇을 분수로 나타내어 보자. 0.7̇을 x라고 하면 $x=0.7777$⋯ ⋯①이고, ①의 양변에 10을 곱하면 $10x=7.7777$⋯ ⋯②이다. 이때 ①과 ②의 소수 부분이 같으므로 ②에서 ①을 번거리 빼면 $9x=7$이다. 따라서 $x=7$/9이다. 즉, 0.7̇$=7$/9임을 알 수 있다.",
