      "problem": "다음은 수학 교사를 위한 '평가' 연수 시간에 이루어진 대화의 일부이다.\n\n김 강사: 서술형 평가의 중요성에 대해 말씀을 드렸습니다. 혹시 질문이 있으세요?\n박 교사: 서술형 평가는 선택형 평가와 비교해 장점도 있지만, 채점의 어려움이 걱정됩니다.\n김 강사: '총체적 점수화 방법'을 적용하여 채점하면 좋을 듯합니다.\n$(\\sqrt{28x}$가 정수가 되는 100 이하의 모든 양의 정수 x의 합을 구하는 서술형 문제. 정답률 51%)\n박 교사: 아, 풀이 전반에 걸쳐 하나의 점수를 부여하는 방법이군요. 다른 채점 방법도 있나요?\n김 강사: 네, '분석적 점수화 방법'이 있습니다. 문제를 해결하는 데 필요한 내용이나 과정을 몇 단계로 구분하여 단계별로 점수를 부여하는 방법입니다.\n\n<채점 기준표> 문제 이해(제곱근의 성질 이해, 2점) / 문제해결$(\\sqrt{28x}$를 $\\sqrt{2}^{2}\\times$ $7\\times$ x 또는 $2\\sqrt{7x}$로 고침, 3점 / 이를 이용해 만족하는 수를 모두 구함, 3점) / 답 구하기(만족하는 모든 수의 합을 구함, 2점)\n<학생 A의 답안> $\\sqrt{x}^{2}=x(x\\geq$ 0)이므로 $\\sqrt{28x}$가 정수가 되기 위해서는 $x=28$이고, 또한 $\\sqrt{28x}=\\sqrt{2}^{2}\\times$ $7\\times$ $x=2\\sqrt{7x}$이므로 $2\\sqrt{7x}$가 정수가 되기 위해서는 $x=7k^{2}$이다. 따라서 만족하는 모든 양의 정수 x의 값은 7, 28, 63이고 그 합은 98이다.\n\n교사의 수업 개선에 초점을 맞추어 서술형 평가의 장점을 <자료 1>, <자료 2>와 관련지어 서술하시오. 또한 <자료 2>의 채점 기준표에 근거하여 '학생 A의 답안'을 채점한 점수를 쓰고, 그 점수를 부여한 이유를 설명하시오. [4점]",
