      "problem": "다음은 수업 준비를 위한 교사용 보조 자료이다. 수학적 사실을 정당화하는 과정에서 두드러지게 나타나는 추론 유형을 (가), (나)에서 각각 하나씩 찾고, 이 두 유형의 추론을 기초로 정당화의 지도 방법을 <작성 방법>에 따라 논술하시오. [10점]\n\n<한 가지 수학적 사실을 정당화하는 두 가지 접근> — 밑변의 양 끝각의 크기가 같은 사다리꼴에서 평행하지 않은 한 쌍의 대변의 길이는 서로 같음을 설명하시오.\n\n(가) 밑변의 양 끝각의 크기가 같은 사다리꼴 모양의 종이를 준비한다. 윗변의 수직이등분선을 따라 접는다. 평행하지 않은 한 쌍의 대변이 일치하므로, 대변의 길이는 서로 같다.\n\n(나) 그림과 같이 AD∥BC이고 $\\angle$ $B=\\angle$ C인 사다리꼴 ABCD가 있다. $AB=DC$임을 보이자. 점 D에서 AB에 평행한 DE를 그으면, 동위각의 성질에 의해서 $\\angle$ $DEC=\\angle$ B이다. 그런데 $\\angle$ $B=\\angle$ C이므로 $\\angle$ $DEC=\\angle$ C이다. 따라서 $\\triangle$ DEC는 이등변삼각형이므로 $DE=DC$이다. 또한 $\\square$ ABED는 평행사변형이므로 $AB=DE$이다. 따라서 $AB=DE$이고 $DE=DC$이므로 $AB=DC$이다.\n\n<작성 방법>\n◦ 서론, 본론, 결론의 형식을 갖출 것.\n◦ 서론 부분에는 (나)와 같은 방법만으로 지도할 때 생길 수 있는 문제점을 포함할 것.\n◦ 본론 부분에는 아래 요소를 포함하여 작성할 것: 폴리아(G. Polya)의 관점에서 두 추론의 역할, 반 힐레(P. van Hiele)의 기하 학습 수준 이론에서 제3수준과 제4수준이 주는 시사점\n◦ 결론 부분에는 2009 개정 교육과정의 '교수·학습 방법'에 제시된 수학적 추론 능력을 신장시키기 위한 유의사항을 포함할 것.",
