      "problem": "2015 개정 교육과정에 따른 중학교 함수 영역에서는 함수 개념 도입 전에 다양한 상황을 그래프로 나타내고 해석하는 것을 다루도록 하고 있다. 두 예비 교사 A와 B는 함수 그래프 지도 이론과 기존 교과서 자료를 이용해 수업을 설계해 보았다.\n\n(가) 예비 교사 A의 활동지: 3개의 용기(원기둥, 원뿔대, 병 모양)에 일정한 속도로 물을 따를 때, 시간에 따라 변하는 물의 높이를 대략적인 그래프 개형으로 나타내고 설명.\n\n(나) 예비 교사 B의 활동지: 1분에 1L씩 물이 나오는 수도꼭지로 물통에 물을 받을 때, x(분)에 따른 y(L)의 값을 표로 완성하고 좌표평면에 그래프를 그리고 설명.\n\n<작성 방법>\n◦ 크라벤담(H. Krabbendam)의 질적 접근과 양적 접근의 관점에서 그래프 지도 방식을 비교할 것.\n◦ 폴리아(G. Polya)의 문제해결 이론에 근거하여 반성 단계에서 적절한 교사의 공통 발문 1가지와 그 이유를 제시할 것.\n◦ (가), (나) 수업 장면에서 주의해야 할 극단적인 교수학적 현상을 각각 1가지씩 다르게 제시할 것.\n◦ 중학교 함수 영역의 그래프에 대한 교수·학습 방법 유의사항을 2015 개정 교육과정에 근거하여 제시할 것.\n◦ 서론, 본론, 결론의 형식을 갖출 것.",
