      "answer": "크라벤담의 관점에서 질적 접근(qualitative approach)은 (가)처럼 정확한 수치 계산 없이 변화의 전반적 경향(증가·감소·오목·볼록 등 그래프의 개형)을 정성적으로 파악하는 데 초점을 두고, 양적 접근(quantitative approach)은 (나)처럼 구체적인 수치(표)를 근거로 정확한 좌표를 찍어 그래프를 정밀하게 구성하는 데 초점을 둔다. 두 접근은 상호 보완적이며, 질적 접근이 그래프에 대한 전체적 직관을 형성한다면 양적 접근은 그 직관을 정밀화한다.\n\n폴리아의 반성 단계에서 (가)와 (나) 문제 모두에 공통적으로 적절한 발문은 \"그래프가 나타내는 변화의 경향이 실제 상황(용기의 모양, 물이 나오는 속도)과 부합하는지 다시 한번 확인해 볼까요?\"이다. 폴리아의 반성 단계는 얻은 결과가 문제 상황에 부합하는지 재검토하는 단계이므로, 두 활동 모두에서 학생이 만든 그래프가 실제 상황의 의미와 일치하는지를 되짚어보게 하는 발문이 공통적으로 적절하다.\n\n(가)를 이용하는 수업 장면에서 주의해야 할 극단적 교수학적 현상은, 정확한 수치 없이 개형만 다루므로 학생이 임의의 그래프를 그리고도 왜 그런지 논리적 근거 없이 \"그럴듯해 보인다\"는 직관에만 의존하게 되는 현상이다. (나)를 이용하는 수업 장면에서 주의해야 할 극단적 교수학적 현상은, 정확한 수치 계산에 지나치게 몰두하여 그래프가 나타내는 전체적 변화의 의미(현상적 해석)를 놓치고 기계적 좌표 찍기에만 그치는 현상이다.\n\n2015 개정 교육과정에 따를 때, 함수 개념 도입 전 단계에서 그래프를 다룰 때는 형식적인 함수식이나 정확한 수치 계산에 치중하기보다 실생활 맥락에서 변화하는 양 사이의 관계를 그래프로 나타내고 해석하는 활동을 통해 함수적 사고의 기초를 다지도록 지도해야 함을 유의사항으로 제시할 수 있다.",
