      "problem": "다음 (가), (나)는 교사 A와 B가 다항식의 곱셈을 지도하는 수업 상황이다.\n\n(가) 교사 A: 공식 $(a+b)^{3}=a^{3}+3a^{2}b+3ab^{2}+b^{3}$을 기억하세요. (예시를 보여준 후) 공식을 이용하여 $(5x+2)^{3}$을 각자 전개해 보세요. 학생: 공식에 대입하여 전개해 보니 $125x^{3}+150x^{2}+60x+8$이 되었어요.\n\n(나) 교사 B: $(a+b)^{3}$을 어떻게 전개하는지 공부하겠습니다. 중학교 때 배운 공식 $(a+b)^{2}=a^{2}+2ab+b^{2}$을 기억하나요? 학생: 네. ㉠$(a+b)^{2}$을 $(a+b)(a+b)$로 바꾸어 전개하면 $a^{2}+2ab+b^{2}$이 되는 것을 알고 있어요.\n교사 B: $(a+b)^{3}$은 $(a+b)$와 $(a+b)^{2}$의 곱으로 나타낼 수 있을까요?\n학생: $(a+b)^{3}=(a+b)(a+b)^{2}$이에요.\n교사 B: 전개할 수 있을까요?\n학생: (잠시 후) ㉡아하, 그러면 $a^{3}+3a^{2}b+3ab^{2}+b^{3}$이네요. 이제 확실히 알게 되었으니, 혼자서도 할 수 있어요.\n\n(가)의 수업 상황에서 발생할 수 있는 극단적인 교수학적 현상이 무엇인지 쓰고 그 이유를 설명하시오. 또한 (나)의 수업 상황에서 ㉠에서 ㉡으로의 '실제적 발달 수준'의 변화 과정을 비고츠키(L. Vygotsky) 학파의 '비계설정(scaffolding)'에 근거하여 설명하시오. [4점]",
