      "problem": "다음은 딘즈(Z. Dienes)의 이론에 기초하여 탐구 활동을 강조한 수학 수업에서 사용할 교구 제작 및 활용을 위한 계획서의 일부이다.\n\n<제작 계획> 1단계: 한 변의 길이가 1인 정사각형 조각들을 사용하여 직사각형 모양 4개를 만든다. 각 직사각형을 만드는 데 사용된 정사각형 조각의 개수는 a₁, a₂, a₃, a₄이다. 2단계: 각각의 직사각형을 만드는 데 사용된 모든 정사각형 조각들을 재배치하면 큰 정사각형 모양으로 만들 수 있다.\n<활용 계획> (가)에 있는 정사각형 조각의 총 개수는 a₁$+a$₂$+a$₃$+a$₄임을 파악한다. (나)에 있는 큰 정사각형의 한 변의 길이는 $1+2+3+4$임을 파악한다. (가)와 (나)에 있는 정사각형 조각의 개수는 서로 같다는 것을 인식한다.\n\n위 교구를 활용한 고등학교 수열 단원 수학 수업에서 학습자가 형성하기를 기대하는 일반화된 식을 쓰고, 그 식을 어떻게 유도하였는지 위 교구와 관련지어 설명하시오. 또한 딘즈의 개념 형성 이론의 관점에서, 수학 학습을 위해 고안된 교구 또는 구체물 속에 내포되어 있어야 하는 것이 무엇인지 쓰시오. [4점]",
