      "answer": "사회적 구성주의(어니스트 등)는 지식이 개인의 인지 구조 안에서만 구성되는 것이 아니라 사회적 상호작용과 합의를 거쳐 객관화된 지식으로 승인된다고 보는 관점으로, 개인 내적 구성만을 강조하는 급진적 구성주의(폰 글라저스펠드)와 차이가 있다. 현실주의적 수학교육에서 수학화란 현실적 문제 상황에서 출발하여 이를 점차 수학적으로 조직화·형식화해 나가는 과정을 의미한다.\n\n<자료 1>의 수업 상황을 사회적 구성주의 이론의 '객관화된 수학 지식을 얻기까지 거쳐야 할 과정'의 관점에서 분석하면, 학생 개인이 발견한 관계(추측)는 다른 학생의 반례 제시와 토론을 거쳐 검증·수정되며, 최종적으로 학급 전체의 합의를 통해 하나의 공인된(객관화된) 수학적 지식(원주각 정리)으로 승인된다. 이는 개인적 지식이 사회적 상호작용과 합의 과정을 거쳐 객관화된 지식으로 전환되는 과정을 보여준다.\n\n<자료 2>의 수업 계획서를 현실주의적 수학교육 이론의 '수학화 과정'의 관점에서 분석하면, 실세계의 비수학적 문제(카메라 각도)에서 출발하여 이를 수학적 문제(각의 최댓값 문제)로 변환하고(수평적 수학화), 원주각의 성질을 활용해 수학적으로 해결하는(수직적 수학화) 전형적인 수학화 과정을 보여준다.\n\n<자료 1>에서 의사소통 역량이 강조되는 이유는, 학생 간 반례 제시와 토론·합의를 통해 지식을 구성하는 과정이 2015 개정 교육과정이 강조하는 다른 사람의 생각을 이해하고 자신의 생각을 표현하는 의사소통 능력 함양 방법과 부합하기 때문이다. <자료 2>에서 문제 해결 역량이 강조되는 이유는, 비구조화된 실세계 문제를 수학적으로 해결하는 과정이 교육과정이 강조하는 다양한 실생활 문제를 수학적으로 해결하는 경험이라는 문제 해결 능력 함양 방법과 부합하기 때문이다.",
