      "problem": "김 교사는 반 힐레(P. van Hiele)의 교수·학습 5단계를 적용하여 고등학교 조합 단원의 수업을 계획하였다. 다음은 수업 과정을 순서 없이 나열한 것이다.\n\n(가) 학생이 조합에 친숙해질 수 있도록 4개 중 2개를 선택하는 경우의 수를 구해 보게 한다. 학습 주제를 소개한다.\n(나) 학생은 경험과 교사의 도움말을 토대로 조합의 구조에 대한 의견을 표현해 봄으로써 그 구조를 명확히 하고 관계 체계를 형성한다.\n(다) 교사는 수형도 등 다양한 방법으로 구할 수 있는 간단한 조합 문제를 제시하여 학생이 해결해 보도록 안내한다.\n(라) 교사는 다양한 탐색적 과제로 구성한 활동지를 제공하여 조합의 구조에 정통하게 한다.\n(마) 학생은 조합과 순열의 관련성을 파악하고 전체적으로 조망하며 사고 수준의 비약에 이른다.\n\n(가)~(마)를 순서대로 배열하고, (마) 단계의 명칭을 쓰시오. [2점]",
