      "problem": "다음은 김 교사가 박 교사의 수업을 참관한 후 작성한 참관 일지의 일부이다.\n\n박 교사는 도입 단계에서 사각형 조각(한 변이 x인 정사각형 1개, 1과 x인 직사각형 2개, 한 변이 1인 정사각형 1개)을 이용해 만든 정사각형의 넓이를 (한 변의 길이$)^{2}$으로 나타내고, 각 사각형의 넓이 합을 식으로 나타내어 등식으로 표현하는 탐구 활동을 제시하였다. 학생은 $x^{2}+2x+1=(x+1)^{2}$이 성립함을 인식하였다. 박 교사는 학생이 구한 식을 이용해 인수분해의 뜻을 알려주고, 이전 시간에 학습한 다항식의 곱셈 공식과의 관계를 찾아보도록 안내하였다. 학생은 곱셈 공식을 이용해 $a^{2}+2ab+b^{2}=(a+b)^{2}$, $a^{2}-2ab+b^{2}=(a-b)^{2}$ 인수분해 공식을 이끌어 내었다.\n\n피아제(J. Piaget)는 활동에 대한 일반적 조정으로부터의 추상화를 무엇이라고 하였는지 쓰시오. 그리고 이 추상화의 예를 위 참관 일지의 상황에서 1가지 찾아, 이 추상화의 과정을 반사와 반성으로 구분하여 그 근거와 함께 설명하시오. [4점]",
