      "answer": "피아제는 활동에 대한 일반적 조정으로부터의 추상화를 반영적 추상화(reflective abstraction)라 하였다. 이는 물리적 대상 자체의 속성에서 얻는 경험적 추상화와 달리, 자신이 수행한 행위(활동)들 사이의 관계·조정으로부터 얻는 추상화이다.\n\n참관 일지 상황에서 이 추상화의 예로, 넓이 계산 활동($x^{2}+2x+1=(x+1)^{2}$)을 인수분해 공식($a^{2}+2ab+b^{2}=(a+b)^{2}$)으로 확장한 과정을 들 수 있다. 이 과정을 반사와 반성으로 구분하면, 반사(reflection, 투사)는 넓이 계산이라는 구체적 활동 수준에서 얻은 관계를 \"인수분해\"라는 새로운 사고 대상으로 투사하는 과정이고, 반성(reflection, 사고적 재구성)은 인수분해라는 새로운 대상 수준에서 이것이 이전에 배운 다항식의 곱셈 공식과 어떤 관계가 있는지 재구성하며 성찰함으로써 일반화된 인수분해 공식을 이끌어내는 과정이다.",
