      "problem": "<자료 1>은 절대부등식을 증명하는 수업 과정에서 학생이 새로운 추측을 제기하는 상황이고, <자료 2>는 김 교사가 그 증명을 지도하기 위해 작성한 교수·학습 계획서의 일부이다. <작성 방법>에 따라 논술하시오. [10점]\n\n<자료 1>: 김 교사가 $x^{2}+y^{2}\\geq$ xy가 성립함을 증명하였다. 학생 1은 $x^{2}+y^{2}+z^{2}\\geq$ xyz도 성립할 것 같다 하고, 학생 2는 $x^{2}+y^{2}+z^{2}\\geq$ $xy+yz+zx$가 성립할 것 같다고 함.\n\n<자료 2>: (가) 두 관점 — 관점 A(수학은 준경험적이고 오류 가능하며 인간의 창조적 활동의 산물, 절대적 확실성을 갖지 않고 끊임없는 개선의 여지가 있음), 관점 B(수학의 형성 과정에서 사회의 역할을 강조, 수학적 지식은 절대적 진리가 아니라 사회적으로 객관적인 것). 명제 증명은 $x^{2}+y^{2}\\geq$ 2xy, $y^{2}+z^{2}\\geq$ 2yz, $z^{2}+x^{2}\\geq$ 2zx를 더하여 정리.\n(나) 평가 계획: 관찰 평가(의사소통: ㉠), 자기 평가(태도 및 실천: ㉡)\n\n<작성 방법>\n◦ 서론: <자료 1>에서 학생이 사용한 추론 유형과 보완해야 할 점\n◦ 본론: 관점 A에서 본 증명의 의미와 교사 활동 1가지, 관점 B에서 본 증명의 의미와 교사 활동 1가지, ㉠과 ㉡에 들어가는 항목 각 1가지(2015 개정 교육과정 근거)\n◦ 결론: 학생의 추론을 정당화 과정으로 연결하는 지도의 의의\n◦ 서론, 본론, 결론의 형식을 갖출 것.",
