      "title": "함수 개념의 역사적 발생 순서 배열",
      "problem": "다음은 함수와 관련한 수학사 자료를 순서 없이 제시한 것이다. (가)~(마)를 함수 개념이 발생한 순서대로 배열하시오. [2점]\n\n(가) 고대 바빌로니아나 그리스에서 천문학을 연구했던 사람들은 태양, 달, 행성 등의 변화를 관찰하여 수표를 작성하였다. 이 시기 사람들은 수표를 사용하여 천체 운동을 서술하고 주기성을 발견하였다. 삼각함수의 기원을 이 시기에서 찾을 수 있다.\n\n(나) 비에트(F. Viète)가 문자를 사용하는 방식을 발전시키고 데카르트(R. Descartes)가 해석기하학을 창안한 것에 기초하여 함수를 대수적으로 연구하게 되었다. f(x)라는 기호를 처음으로 사용한 오일러(L. Euler)는 변수와 상수가 결합된 방식에 따라 함수를 분류했다. 이 시기에 이르러 독립변수와 종속변수의 구분이 명확해졌다.\n\n(다) 해석학을 엄밀하게 만들기 위해 함수의 연속성과 미분가능성에 대한 연구가 이루어졌다. 데데킨트(R. Dedekind), 칸토어(G. Cantor) 등이 실수의 구조를 엄밀하게 하여 해석학을 발전시켰다. 부르바키(Bourbaki) 학파는 집합론에 기초하여 '순서쌍의 집합의 부분집합'이 어떤 특정한 조건을 만족할 때 그 부분집합을 함수로 정의하였다.\n\n(라) 이 당시 학자들은 주로 운동을 나타내는 곡선을 중심으로 곡선의 접점, 곡선 아래의 넓이, 곡선의 길이, 곡선을 따라 움직이는 점의 속도 등을 연구하였다. 갈릴레이(G. Galilei)는 등가속도 운동을 하는 물체가 움직인 거리와 시간의 관계를 연구하였는데, 과학에서 이루어진 운동에 대한 연구가 함수를 개념화하는 데 기여하였다.\n\n(마) 푸리에(Fourier) 급수나 디리클레(Dirichlet) 함수에 대한 연구 결과로 인하여 함수 개념을 새롭게 정의할 필요성이 생겨났다. 일가성과 임의성을 가지는 대응으로 함수를 정의함으로써 한 변수의 각 값에 다른 변수의 유일한 값이 대응되느냐 되지 않느냐는 논리적 조건에만 관심을 갖게 되었다.",
