      "answer": "함수 개념은 역사적으로 \"관측 자료의 정리 → 운동의 수학적 서술 → 대수적 형식화 → 대응으로서의 일반화 → 집합론적 엄밀화\"의 흐름으로 발전하였다.\n\n배열 순서는 (가)-(라)-(나)-(마)-(다)이다.\n첫째, (가)는 바빌로니아·그리스 천문학의 관측 수표 작성 시기로, 함수 개념의 맹아라 할 수 있는 규칙적 대응표가 처음 나타난 가장 이른 시기이기 때문이다.\n둘째, (라)는 갈릴레이의 운동학 연구 시기로, 시간과 거리 같은 두 변화하는 양 사이의 관계를 다루기 시작하여 함수적 사고의 토대를 마련한 시기이기 때문이다.\n셋째, (나)는 비에트·데카르트·오일러를 거치며 함수가 문자와 기호를 통해 대수적 형식(공식)으로 명확히 표현되고 독립변수·종속변수 구분이 확립된 시기이기 때문이다.\n넷째, (마)는 푸리에·디리클레의 연구를 계기로 함수가 공식이 아니라 임의의 대응 관계로 일반화된 시기이기 때문이다.\n다섯째, (다)는 데데킨트·칸토어의 실수론과 부르바키의 집합론에 기초하여 함수가 순서쌍의 집합으로 가장 엄밀하게 정의된, 가장 나중의 시기이기 때문이다.",
