      "answer": "두빈스키의 APOS 이론에서 행동은 절차를 단계별로 수행하는 수준이고, 과정은 그 절차를 내면화하여 굳이 각 단계를 밟지 않고도 전체를 사고할 수 있는 수준이며, 대상은 그 과정을 하나의 완결된 실체로 캡슐화하여 조작 대상으로 다루는 수준이다.\n\n민수의 학습 일지는 행동과 과정으로 설명할 수 있다.\n첫째, 민수는 조립제법이라는 절차를 단계별로 정확히 수행할 수 있는 행동 수준에 도달해 있다. 그는 주어진 나눗셈 문제를 조립제법 절차에 따라 실제로 풀어낼 수 있기 때문이다.\n둘째, 그러나 민수는 그 절차 전체를 하나의 흐름으로 내면화하여 \"계산 과정 자체\"를 설명하는 과정 수준에는 아직 도달하지 못했다. 절차를 실행할 수는 있어도 그 절차가 왜 그렇게 진행되는지 전체적으로 조망하여 설명하지는 못했기 때문이다. 반면 컴퓨터 프로그램을 다룰 줄 모르는 친구가 오히려 그 계산 과정을 잘 설명한 것은, 절차의 실행(행동) 없이도 전체 흐름을 사고하는 과정 수준의 이해를 갖추고 있었기 때문으로 해석할 수 있다.\n\n재희의 학습 일지는 과정과 대상으로 설명할 수 있다.\n첫째, 재희가 함수를 \"x값을 넣으면 y값이 나오는 것\"으로 이해하는 것은 함수를 하나의 입력-출력 절차, 즉 과정 수준에서 이해하고 있음을 보여준다. 함수를 수행되는 계산 절차로만 인식하고 있기 때문이다.\n둘째, 재희가 \"함수를 수처럼 다룰 수 있는가\"에 대해 의문을 갖는 것은, 함수(과정)를 하나의 완결된 대상으로 캡슐화하여 덧셈과 같은 새로운 연산의 대상으로 다루는 대상 수준의 이해에는 아직 도달하지 못했음을 보여준다. 함수를 여전히 \"수행되는 절차\"로만 여기고 있어, 그것을 정적인 하나의 실체(대상)로서 다른 함수와 연산할 수 있다는 것을 받아들이기 어려워하기 때문이다.",
