      "problem": "다음은 윤 교사가 고등학교 수학 '도형의 방정식' 단원에서 사용한 활동 과제 중 3가지를 나타낸 것이다.\n\n(1) 축구공이 골라인을 나타내는 직선 $l$을 지나가는 상황을 차례로 찍은 사진([그림 1]~[그림 3])에서 각각 직선 $l$을 x축으로 하여 좌표축을 설정하고 축구공을 나타내는 원을 식으로 표현하시오.\n(2) 좌표평면에서 원과 직선의 위치 관계를 알아보시오.\n(3) 원 $x^{2}+y^{2}=r^{2}$과 직선 $y=px+q$의 위치 관계를 이차방정식의 판별식을 이용하여 설명하시오.\n\n트레퍼스(A. Treffers)가 제시한 수평적 수학화와 수직적 수학화의 의미를 설명하고, 윤 교사의 활동 과제를 수평적 수학화와 수직적 수학화의 관점에서 분석하여 서술하시오. [4점]",
