      "answer": "트레퍼스가 제시한 수평적 수학화는 현실 세계의 비수학적 문제 상황을 수학적 기호나 모델로 옮기는 과정이며, 수직적 수학화는 이미 수학화된 내용을 더 형식적이고 일반적인 수학 체계 내에서 재조직하는 과정이다.\n\n윤 교사의 활동 과제를 두 개념의 관점에서 분석하면 다음과 같다.\n첫째, (1)의 활동은 수평적 수학화에 해당한다. 축구공이 골라인을 지나가는 실제 사진이라는 비수학적·현실적 상황을 좌표축과 원의 방정식이라는 수학적 표현으로 처음 변환하는 과정이기 때문이다.\n둘째, (2)와 (3)의 활동은 수직적 수학화에 해당한다. (1)에서 이미 수학화된 원의 방정식을 바탕으로, 직선과의 위치 관계를 이차방정식의 판별식이라는 더 형식적이고 일반적인 수학적 도구를 이용해 재조직하고 일반화하고 있기 때문이다.\n\n즉 윤 교사의 활동 과제는 (1)의 수평적 수학화로 현실 상황을 수학의 세계로 끌어들인 뒤, (2)와 (3)의 수직적 수학화를 통해 그 수학적 표현을 더 정교하고 일반적인 형식(판별식을 이용한 위치 관계 판정)으로 발전시켜 나가는 구조로 되어 있다.",
