      "problem": "다음은 라카토스(I. Lakatos)의 준경험주의 수리철학에 대한 두 교사의 대화이다.\n\n이 교사: 라카토스에 따르면 수학적 지식은 반증되기 전까지 잠정적으로 참이며, 증명은 원래의 추측을 부분 추측으로 분해하는 사고 실험이에요.\n김 교사: 수학적 추측이 증명되었을 때 그 추측을 반박하는 전면적 반례가 등장하면 어떻게 하나요?\n이 교사: 대응하는 방식이 여러 가지가 있는데요. 한 방식은 ㉠이미 증명된 추측은 그대로 두고 오히려 반례가 잘못되었다고 보아 원래의 추측을 존속시키는 거예요. 이 방식은 반례와 관련된 개념을 추측이 성립하는 영역 밖으로 몰아내는 것에 주로 관심을 두어 개념을 재정의하지요.\n김 교사: 또 다른 방식은 어떤 것이 있나요?\n이 교사: ㉡전면적 반례가 출현하게 된 원인이 되는 부분 추측을 찾아 원래의 추측에 합체시키고 증명과 추측을 개선하는 방식이 있어요. 이 방식에서 전면적 반례는 동시에 국소적 반례도 되지요. 이 방식을 통해 발견과 정당화의 논리가 분리되지 않고 하나로 통합될 수 있어요.\n\n전면적 반례에 의해 추측이 비판되었을 때 대응하는 방식 ㉠과 ㉡을 라카토스가 제시한 용어로 순서대로 쓰시오. [2점]",
