      "problem": "원의 현에 관한 성질 중 한 가지를 지도하기 위해 교사가 <자료 1>과 <자료 2>를 개발하였다.\n\n<자료 1> ① 원 모양의 종이에 현 AB를 그린다. ② 점 A와 점 B가 겹쳐지도록 접었다가 펼친다. ③ ②에서 접은 선을 $l$이라 하고, $l$과 현 AB가 만나는 점을 M이라고 한다. 질문: 직선 $l$이 원의 중심을 지나는가? 직선 $l$이 현 AB와 이루는 각의 크기는 얼마인가? $\\overline{AM}$과 $\\overline{BM}$의 길이를 비교하시오.\n\n<자료 2> 원 O의 중심에서 현 AB에 내린 수선의 발을 M이라고 하면 △OAM과 △OBM에서 $\\overline{OA}=\\overline{OB}$(반지름), $\\angle OMA=\\angle OMB=90^{\\circ}$, $\\overline{OM}$은 공통이므로 직각삼각형의 합동 조건에 의하여 $\\triangle OAM \\equiv \\triangle OBM$이다. 따라서 $\\overline{AM}=\\overline{BM}$이다. 이로부터 다음을 알 수 있다. ( ㉠ )\n\n<자료 1>과 <자료 2>를 통해 교사가 공통으로 가르치려는 원의 현에 관한 성질 ㉠을 서술하시오. 그리고 <자료 1>과 <자료 2>에서 사용한 정당화 방법이 무엇인지 각각 쓰고, 두 자료를 학생 수준에 맞게 수업에서 어떻게 활용할지 서술하시오. [4점]",
