      "problem": "다음은 김 교사의 교수·학습 지도안에 대하여 교사들이 나눈 대화이다.\n\n김 교사: 교수·학습 지도안을 작성해 보았습니다. 학습 목표는 무리수의 개념을 이해하는 것입니다. 전개 단계에서 스프레드시트를 이용하여 $\\sqrt{2}$가 순환하지 않는 무한소수임을 설명합니다.\n최 교사: $\\sqrt{2}$가 순환하지 않는 무한소수임을 설명하기 위해 공학적 도구를 이용하였네요. 2015 개정 수학과 교육과정에 이에 대한 근거가 있나요?\n김 교사: 네, ㉠정보 처리 능력을 함양하기 위한 교수·학습 방법에 명시된 내용이 있습니다.\n최 교사: 그렇군요. 저도 수업 시간에 스프레드시트를 이용한 적이 있는데, ㉡학생들이 $\\sqrt{2}$가 순환하지 않는 무한소수라는 것에는 관심을 두지 않고 \"선생님, 무슨 식을 입력하였기에 x에 수를 넣으면 $x^{2}$이 계산되는 건가요? 스프레드시트 다루는 방법 좀 알려주세요\"라는 말을 해서 난감했던 적이 있었습니다.\n\n김 교사가 교수·학습 지도안에서 스프레드시트를 이용한 근거를 ㉠의 구체적인 내용으로 제시하시오. 그리고 브루소(G. Brousseau)의 교수학적 상황론에서 ㉡을 설명할 수 있는 극단적인 교수 현상을 쓰고, 그 현상을 ㉡의 상황과 관련지어 설명하시오. [4점]",
