      "answer": "㉠의 구체적인 내용은, 2015 개정 수학과 교육과정의 정보 처리 능력 함양을 위한 교수·학습 방법에 제시된 \"공학적 도구를 이용하여 수학적 개념, 원리·법칙을 탐구하고 이해하도록 지도한다\"는 사항이다. 스프레드시트로 $\\sqrt{2}$의 근삿값 변화를 직접 계산하며 탐구하게 하는 것이 이 지침에 해당하는 활동이기 때문이다.\n\n㉡과 같은 극단적인 교수 현상은 브루소의 교수학적 상황론에서 설명할 수 있는데, 이는 교구(공학적 도구)가 원래 의도된 수학적 지식을 압도하여 도구 자체의 사용법이 학습의 목적이 되어버리는 현상이다.\n\n이 현상이 ㉡의 상황에서 일어나는 이유는, 학생들이 스프레드시트라는 새로운 도구에 익숙하지 않아 그 조작 방법 자체에 관심이 쏠리면서, 정작 교사가 의도했던 수학적 목표($\\sqrt{2}$가 순환하지 않는 무한소수라는 개념적 이해)로부터 주의가 벗어나 버렸기 때문이다. 즉 도구가 지식 전달의 수단이 아니라 그 자체가 학습의 대상이 되어버리는 목적 전치가 발생한 것이다.",
