      "problem": "다음은 19세기말부터 100여 년 동안 이루어진 수학교육의 변천에 관한 자료를 순서 없이 제시한 것이다. (가)~(마)를 수학교육의 역사적 흐름에 따라 순서대로 배열하시오. [2점]\n\n(가) '기본으로 돌아가기 운동(The Back-to-Basics Movement)'의 영향으로 학교수학에서는 기본 기능을 강조하는 방향으로 교재를 재구성하였다. 그러나 우수한 학생들의 학력이 저하되고 응용력과 문제 해결 능력이 감소되기도 하였다.\n\n(나) 전통적인 방식으로 유클리드 기하를 가르치는 것에서 벗어나 실험 기하를 가르치고, 수학의 실용성, 유용성 등을 강조하였다. 학교수학의 내용을 체계적으로 다듬으려는 노력이 시작되었으며, 학교수학에 함수 개념을 도입한 교과서가 출판되었다.\n\n(다) 지식의 획득에서 지식의 구성으로, 문제 해결에서 문제 제기로 수학교육의 강조점을 변화시키자는 흐름이 본격적으로 일어났다. 그리고 '수학 학습 수준 이론', '현실주의적 수학교육(Realistic Mathematics Education)' 등 여러 이론과 모델이 발전하였다.\n\n(라) 과학기술의 급격한 발달에 따라 수학의 응용 범위가 확대되었으나 학교수학의 내용이 시대에 뒤떨어진다는 반성으로 집합, 함수, 대수적 개념, 확률 등을 조기에 도입하고자 하였다. 이 시기에 일어난 변화는 우리나라 제3차 교육과정에 영향을 미쳤다.\n\n(마) 근대화된 사회의 모습을 반영하여 수학교육을 개선해야 한다는 주장이 제기되었다. 엄밀하고 논리적 체계를 갖춘 유클리드 원론 중심의 수학교육, 형식 도야라는 명분으로 과도한 훈련을 하는 수학교육, 소수 특권층을 위한 수학교육 등 당시의 수학교육 실태를 개선하여야 한다는 비판이 있었으나 실제로 크게 개선되지는 못했다.",
