      "answer": "수학교육의 역사적 흐름은 \"고전적 형식도야 중심 교육에 대한 비판 → 실용성 강조 개혁 → 신수학운동 → 기본으로 돌아가기 운동 → 구성주의·현실주의 수학교육\"의 순서로 전개되었다.\n\n배열 순서는 (마)-(나)-(라)-(가)-(다)이다.\n첫째, (마)는 20세기 초 유클리드 원론 중심의 형식 도야적 수학교육에 대한 비판이 제기된 가장 이른 시기이기 때문이다.\n둘째, (나)는 페리·클라인 등이 주도한 개혁운동 시기로, 실용성과 유용성을 강조하며 실험 기하와 함수 개념을 도입한 시기이기 때문이다.\n셋째, (라)는 2차 세계대전 이후 과학기술 발달에 대응하여 집합·함수 등을 조기 도입한 신수학운동(New Math) 시기이며, 우리나라 제3차 교육과정에 영향을 미쳤다고 명시되어 있어 시기를 특정할 수 있기 때문이다.\n넷째, (가)는 신수학운동으로 인한 학력 저하 문제에 대한 반작용으로 등장한 기본으로 돌아가기 운동(1970년대) 시기이기 때문이다.\n다섯째, (다)는 구성주의, 문제 제기, 현실주의적 수학교육 등이 발전한 가장 최근의 흐름이기 때문이다.",
