      "problem": "다음 <자료 1>은 중학교 3학년 학생 A의 수학일기의 일부이고, <자료 2>는 <자료 1>에 대하여 교사들이 나눈 대화이다.\n\n<자료 1> 친구 B와 시네마 영화관을 갔다. 여러 개의 영화를 동시에 상영하고 있어 영화를 고르기가 힘들었는데, 영화 관람을 마치고 나오는 사람들에게 관람한 영화가 무엇이었는지 조사해 보자는 아이디어가 떠올랐다. 나는 별생각 없이 조사한 자료로 수학 시간에 배운 평균을 구하자고 B에게 말하였다. 그런데 ㉠B가 \"자료를 대표하는 값은 여러 가지가 있고, 주어진 자료에 따라 적절한 값을 사용해야 그 자료의 특성을 대표할 수 있다.\"라고 하면서 우리가 함께 관람하기로 한 영화 선택의 조건이 무엇이었는지 나에게 상기시켜 주었다. \"맞아, 그거야! 여기서는 최빈값이 대푯값으로 적절하겠구나.\"라는 것을 깨달았다. 그리고 보니 오늘 가장 좋았던 것은 ㉡교과서의 정리된 수학이 아닌 내 주변에 살아있는 수학을 경험한 것이었다.\n\n<자료 2> 김 교사: 수학이 우리 삶 가운데 유용하게 사용되고 있음을 알도록 학생들에게 수학일기를 써 보게 했습니다.\n박 교사: 좋은 생각입니다. 학생들이 수학을 왜 배워야 하는지 모르겠다고 하는데 수학일기를 통해 수학의 실용적 가치를 깨닫는 좋은 기회가 될 것 같습니다.\n김 교사: 네, 그리고 동시에 ㉢수학이 객관적 진실이라기보다는 우리의 삶의 경험을 조직하는 데 도움이 됨을 학생들이 인식하면 좋겠습니다.\n\n비고츠키(L. Vygotsky) 학파의 관점에서 <자료 1>의 ㉠을 설명할 수 있는 개념 용어를 쓰고, A가 알게 된 최빈값의 의미를 쓰시오. 그리고 <자료 1>의 ㉡, <자료 2>의 ㉢에 근거하여 사회적 구성주의와 차별화되는 급진적 구성주의의 원리를 설명하시오. [4점]",
