      "answer": "박 교사의 <수업 방향>에 적합한 교수·학습 방법은 협력 학습(소집단 협력 학습)이다.\n\n이 방법을 선택한 이유는 다음과 같다.\n첫째, 협력 학습은 학생들이 모둠 내에서 서로 역할을 나누어 자료를 탐구하고 발표를 준비하게 함으로써, 학생 스스로 학습에 대한 권리와 책무성을 갖게 하기 때문이다.\n둘째, 협력 학습은 학생 간 활발한 토의와 상호작용을 전제로 하므로, <수업 방향>에서 요구하는 학생 간 충실한 상호작용을 자연스럽게 실현할 수 있기 때문이다.\n셋째, 그래프(시각적 표상)를 함께 관찰하고 그 성질을 말과 글(언어적 표상), 식(기호적 표상)으로 정리해 발표하는 과정에서 다양한 표상을 사용하는 능력이 함양되기 때문이다.\n\n협력 학습을 적용할 때 (다)에서 학생이 할 발표의 준비 과정과 내용은 다음과 같다. 준비 과정으로는, 모둠원들이 (나)에서 각자 그린 $y=a\\sin x$, $y=\\sin(bx)$ 그래프들을 온라인 화면 공유를 통해 함께 비교하고, $a$와 $b$의 값 변화가 그래프의 진폭과 주기에 각각 어떤 영향을 주는지 토의를 통해 정리하는 과정을 거친다. 발표 내용으로는, $a$의 절댓값이 커질수록 그래프의 진폭이 커진다는 것과 $b$의 절댓값이 커질수록 그래프의 주기가 짧아진다는 것을 종합하여, $y=a\\sin(bx)$의 그래프가 진폭 $|a|$와 주기 $\\dfrac{2\\pi}{|b|}$를 갖는다는 일반화된 성질을 발표한다.",
