      "problem": "다음은 윤 교사와 강 교사가 수업을 반성하는 대화의 일부이다.\n\n윤 교사: 그림과 같이 지름의 길이가 6인 원 O 위의 점 A에서 지름에 내린 수선의 발을 B라 하고, $\\overline{AB}=2$일 때, 원의 중심 O에서 점 B까지의 거리 $x$의 값을 구하게 하였더니 어떤 학생이 $x$의 값을 구하지 못하더군요. 피타고라스 정리를 알고 이차방정식을 비교적 잘 푸는 학생임에도 불구하고 말이지요.\n\n강 교사: ㉠선분 OA를 직각삼각형 OAB의 빗변으로 보면서 동시에 원 O의 반지름으로 보는 것과 같이 문제의 내적인 구조적 관련성을 파악하는 과정이 없었던 것이 아닐까요?\n\n윤 교사: 저도 그렇게 생각합니다. ㉡전체에 대한 부분의 구조적 기능이 파악되어 '구조의 개선적 변화'가 일어나는 지적 과정에 더욱 관심을 기울여야겠다는 생각을 하게 되었습니다.\n\n형태심리학에서 ㉠을 설명하는 용어와 베르트하이머(M. Wertheimer)가 ㉡을 설명하는 용어를 순서대로 쓰시오. [2점]",
