      "title": "베커의 통계 교육 이론 — 큰 수 추정 활동의 교육적 의의",
      "problem": "다음은 김 교사가 베커(A. Bakker)의 통계 교육 이론에 기초하여 중학교 3학년 통계 단원 수업을 한 후 작성한 수업일지의 일부이다.\n\n나는 도입 단계에서 다음과 같은 <자료>를 학생들에게 제시하며 통계가 현실과 단절된 수량적인 자료의 계산 체계가 아님을 알려주고자 하였다.\n\n<자료> 어느 학자에 따르면, 역사적으로 평균 개념은 큰 수를 대략적으로 추정하기 위한 상황에서 활용되었다고 한다. 고대 인도의 이야기 속 주인공은 나무 한 그루에 달린 나뭇잎과 과일의 총수를 알아보기 위해 우선 평균 크기의 나뭇가지를 선택하고, 그 나뭇가지에 달린 나뭇잎과 과일 수를 헤아린 후 전체 나무에 달린 나뭇잎과 과일 수를 추정하였다.\n\n본시 학습에서는 그림 속 양의 개체수를 추정하는 활동 과제를 제시하였다. 각각의 학생들은 자신만의 큰 수 추정 방법을 활용하여 몇 마리의 양이 있는지를 (a), (b), (c), (d)와 같이 찾아내었다.\n(a) 묶음을 만들어서 각 묶음에 실제로 몇 마리의 양이 있는지 세어 합하였다.\n(b) 하나의 수를 먼저 정한 후, 그 수만큼의 양이 들어 있는 묶음을 표시하고 그 크기의 묶음이 몇 개인지를 어림하여 계산하였다.\n(c) 그림의 왼쪽 모서리와 오른쪽 모서리를 따라 각각 양의 수를 구한 후, 그 두 수를 곱하여 전체 양의 수를 어림하였다.\n(d) 격자를 만들어 격자 속 양의 수가 평균적인 것에 해당되는 것을 고른 후 그 안에 들어 있는 양의 수를 세어 격자의 수에 곱하였다.\n\n㉠ 학생들은 통계의 주요 개념의 역사를 살펴보면서 주어진 상황을 탐색하고, 상황 속 문제 해결의 방법을 배웠다.\n\n베커의 이론에 기초한 통계 수업을 진행할 때 얻을 수 있는 교육적 의의를 위 수업일지에 근거하여 2가지 제시하시오. 그리고 ㉠과 관련지어 (a)와 (d)를 비교하여 설명하시오. [4점]",
