      "answer": "베커의 이론에 기초한 통계 수업을 진행할 때 얻을 수 있는 교육적 의의는 다음과 같다.\n첫째, 학생들이 통계적 개념(평균)을 형식적 공식으로 처음부터 배우는 것이 아니라, 역사적 맥락(고대 인도 이야기) 속에서 그 개념이 왜, 어떻게 필요했는지를 이해하며 재발명할 수 있다는 것이다. 개념이 발생한 맥락을 경험해야 그 개념의 필요성과 의미를 진정으로 이해할 수 있기 때문이다.\n둘째, 학생 개개인이 자신만의 비형식적 추정 전략을 자유롭게 개발하고 이를 점차 정교화해 나가는 과정에서 통계적 사고가 자연스럽게 발달한다는 것이다. 정해진 절차를 암기하는 대신 스스로 전략을 구성해야 개념에 대한 깊은 이해가 형성되기 때문이다.\n\n㉠과 관련지어 (a)와 (d)를 비교하면 다음과 같다. (a)는 묶음을 만들어 각 묶음의 양을 일일이 세어 합산하는 방식으로, 아직 표본을 이용한 어림 전략을 사용하지 않는 비형식적이고 직접적인 접근이다. 반면 (d)는 격자 중 평균적인 크기를 가진 하나의 격자를 표본으로 선택하고 그 값에 전체 격자 수를 곱하여 어림하는 방식으로, <자료>에 제시된 고대 인도 이야기의 \"평균 크기의 나뭇가지를 표본으로 삼아 전체를 추정\"하는 방법과 구조적으로 동일한, 평균 개념의 초기 형태를 활용한 더 형식화된 접근이다. 즉 (a)에서 (d)로 갈수록 학생의 전략은 직접 세는 방식에서 표본과 평균을 이용한 추정 방식으로 발전해 나간 것으로 볼 수 있다.",
