      "problem": "다음은 김 교사가 계획한 중학교 3학년 원의 현에 대한 단원의 교수·학습 지도안의 일부이다.\n\n학습 목표: 원의 현에 관한 성질을 이해한다.\n\n도입: 준비 학습(전시 학습 상기), 동기 유발(실생활에서 원의 성질을 응용한 사례), 본시 학습 목표 확인.\n\n전개(활동1): 원 모양의 색종이를 반으로 두 번 접어 원의 중심 O를 찾는다. 다시 처음 상태로 색종이를 반으로 접고 접은 후 펼친다. 네 점 A, B, C, D를 잡는다. 점 A와 B, 그리고 점 C와 D가 서로 겹치도록 색종이를 각각 접었다 펼친 후, 현 AB의 중점 M과 현 CD의 중점 N을 찾는다. $\\overline{OM}=\\overline{ON}$임을 확인한다.\n\n전개(활동2): 친구들과 자유롭게 토의·토론하면서 활동1을 통해 '길이가 같은 두 현은 원의 중심으로부터 같은 거리에 있다.'는 성질을 학생이 정리할 수 있도록 허용적인 분위기를 조성한다. 학생이 정리한 현에 관한 성질에서 '원의 중심으로부터 같은 거리에 있는 두 현의 길이는 같다.'는 성질을 재구성해 보도록 안내한다. 현에 관한 성질을 연역적으로 논증하기 등 학생 수준에 맞게 정당화 방법을 활용한다.\n\n정리: 본시 학습 내용을 정리한다. 다음 차시를 예고한다.\n\n딘즈(Z. Dienes)가 제안한 수학 학습 원리 중 1가지를 사용하여 교수·학습 지도안의 전개 단계를 활동1→활동2로 실행하려는 이유를 설명하시오. 그리고 활동2 과정 없이 '도입→전개(활동1)→정리'로 수업을 진행한다고 했을 때 김 교사의 수업을 피아제(J. Piaget)의 반영적 추상화의 메커니즘과 관련지어 평가하시오. [4점]",
