      "answer": "딘즈가 제안한 수학 학습 원리 중 역동성의 원리(dynamic principle)를 적용하면, 진정한 학습은 놀이 단계(자유로운 탐색)에서 구조화된 활동을 거쳐 정착 단계(형식화)로 점진적으로 이루어져야 한다.\n\n전개 단계를 활동1에서 활동2로 실행하려는 이유는 다음과 같다. 첫째, 활동1은 종이접기라는 구체적 조작 활동을 통해 $\\overline{OM}=\\overline{ON}$이라는 관계를 직접 확인하는 단계로, 아직 형식화되지 않은 구체적 경험의 단계이기 때문이다. 둘째, 활동2는 그 구체적 경험을 학생 스스로 언어로 재구성하고 나아가 연역적으로 정당화하는 단계로, 딘즈의 역동성의 원리에 따라 구체적 조작에서 형식적 정당화로 점진적으로 나아가야 참된 개념 형성이 이루어지기 때문이다. 즉 활동1만으로는 조작적 확인에 그치고, 활동2를 거쳐야 학생의 이해가 형식적 수준까지 심화될 수 있다.\n\n활동2 과정 없이 '도입→전개(활동1)→정리'로 수업을 진행할 경우, 이를 피아제의 반영적 추상화 메커니즘과 관련지어 평가하면 다음과 같다. 활동1의 종이접기 조작을 통해 학생은 구체적 활동에서 얻은 관계($\\overline{OM}=\\overline{ON}$)를 하나의 사고 대상으로 투사하는 반사(reflection, 투사)는 경험할 수 있다. 그러나 활동2 없이 곧바로 정리로 넘어가면, 그 대상을 두고 왜 그러한 관계가 성립하는지 성찰하며 더 일반화된 명제(\"중심으로부터 같은 거리→같은 길이\"라는 역명제까지 포함)로 재구성하는 반성(reflection, 사고적 재구성)의 기회를 학생이 갖지 못하게 된다. 따라서 이 경우 김 교사의 수업은 피아제가 말하는 반영적 추상화의 완전한 과정(반사와 반성 모두)을 거치지 못한 채, 반사 단계에 머무르는 불완전한 개념 형성에 그칠 위험이 있다고 평가할 수 있다.",
