      "problem": "다음은 ○○고등학교의 학생회가 주최하는 행사의 포스터를 보고 두 교사가 나눈 대화이다.\n\n포스터: '이웃 사랑 챌린지' — 참가자가 줄넘기 300회 미션을 수행한 후 두 명을 지목하면, 지목받은 참가자들이 미션을 수행하고 각자 또 두 명을 지목하는 방식으로 진행. 참가자 한 명당 기부금 10,000원 적립. 30,000,000원 목표.\n\n윤 교사: 학생들이 자발적으로 좋은 일을 하고 있네요.\n강 교사: 저는 이 행사를 홍보하고 추진하는 데 도움을 주고자 수학 수업에서 이 내용을 다뤄 보고자 해요. ㉠크라벤담(H. Krabbendam)의 그래프에 대한 질적 접근 관점에서 이웃 사랑 챌린지가 진행되는 상황을 다루는 수업을 해 볼까 합니다.\n윤 교사: 그 후에 ㉡그래프를 좀 더 정확하게 표현하는 정교화 활동을 하면 어떨까요?\n윤 교사: 저도 이웃 사랑 챌린지를 수업에서 다뤄 봐야겠어요. 학생들이 기획한 이웃 사랑 챌린지를 실세계 현상으로 하여 30,000,000원을 모으려면 최소 몇 단계까지 미션을 수행해야 하는지 알아보게 하는 거죠. 물론 학생들이 계획한 대로 이상적으로 진행된다고 가정해서요. (1단계-2명, 2단계-4명, ... 나무 형태로 확산되는 그림 제시) 그러면 학생들이 수학적 모델을 만들고 분석해서 수학적 결과를 생성한 후 현상에 맞게 결론을 도출하게 될 거예요.\n\n밑줄 친 ㉠에 포함해야 할 활동을 서술하시오. 그리고 윤 교사의 수업에서, 이웃 사랑 챌린지가 이상적으로 진행된다고 가정할 때 학생들이 실세계 현상으로부터 만들어야 할 수학적 모델과 도출해야 하는 결론을 각각 쓰시오. [4점]",
