      "problem": "다음은 수학사의 활용에 대해 논의하고 있는 교사들의 대화이다.\n\n박 교사: 수학사를 수업에서 활용하는 방법에는 어떤 것이 있을까요?\n최 교사: 저는 수학자들의 이야기를 해 주면서 학생들의 흥미를 유발한 적이 있습니다. 아주 옛날에는 문제의 풀이를 일상 언어만으로 기술했지만 약 3세기 디오판토스(Diophantus) 이후 미지수를 문자로 표현하였고, 16세기 프랑스의 수학자 비에트(F. Viète) 이후 ㉠방정식에서 문자의 사용 범위가 확대되었다는 이야기를 해 주었습니다.\n김 교사: 저는 학생들에게 피타고라스 정리가 성립함을 설명하는 방법이 많다고 얘기해 주면서, 인도의 수학자 바스카라(A. Bhaskara)가 제시한 그림에서 피타고라스 정리가 왜 성립하는지 알아보는 활동을 하게 한 적이 있어요.\n박 교사: 교육과정 내용을 재구성할 때도 수학사를 참고할 수 있어요. ㉡수학을 발생된 것으로 파악하고 학습자가 학습 과정에서 수학의 발생을 경험하게 하는 원리에 따라서요. 뢰플리츠(O. Toeplitz)의 『미분적분학』에서 이 원리를 반영하고 있죠.\n김 교사: ㉢뢰플리츠와 방식은 다르지만 프로이덴탈(H. Freudenthal)도 수학사를 교육적으로 활용해야 한다고 했어요.\n\n방정식의 일반해를 나타낼 수 있게 되었다는 점에서 밑줄 친 ㉠의 확대된 문자의 사용 범위를 구체적으로 쓰시오. 또한, 밑줄 친 ㉡이 뜻하는 용어가 무엇인지 쓰고, 밑줄 친 ㉢에서 '수학사를 교육적으로 활용'한다는 것의 의미를 설명하시오. [4점]",
