      "problem": "다음은 대표적인 수학교육 개혁운동 2가지를 설명한 것이다. (가)와 (나)에 해당하는 수학교육 개혁운동의 명칭을 순서대로 쓰시오. [2점]\n\n(가) 19세기 말과 20세기 초부터 유럽과 미국을 중심으로 수학의 실용성을 강조하고 학생의 심리적 측면을 고려하는 방향으로 수학교육을 개혁하려는 운동이 일어났다. 영국의 페리(J. Perry), 독일의 클라인(F. Klein), 미국의 무어(E. Moore) 등이 이 운동에서 주도적인 역할을 하였는데, 여러 국가 사이의 협력을 통해 개혁을 추구하는 방향으로 전개되었다. 하지만 제1차와 제2차 세계대전이 일어나면서 더 진전되지 못했다.\n\n(나) 제2차 세계대전의 종전 이후에 세계적으로 수학교육을 개혁하려는 운동이 다시금 전개되었다. 듀돈네(J. Dieudonné)는 '현대수학의 내용과 방법을 학교수학에 조기에 도입하는 것', '대수적 구조와 논리적 엄밀성을 강조하는 것'과 같은 개혁방향을 제안하였다. 이 같은 방향으로 이 운동을 구체화하는 시도가 여러 국가에서 이루어졌다. 하지만 급진적 개혁을 성급하게 추구한 나머지, 교육적으로 많은 부작용을 초래하였다.",
