      "problem": "다음은 대푯값을 다루는 중학교 수업의 일부이다.\n\n교사: 선생님이 칠판에 적은 ㉠5개의 수는 cm 단위를 빼고서 우리 학교 농구팀 주전 선수 5명의 신장을 적은 것입니다. 이 자료의 대푯값으로 평균이 적합할까요?\n학생 1: 여기서는 평균이 대푯값으로 적합하지 않은 것 같은데요.\n학생 2: 우리 농구팀 주전 선수들의 구성이 좀 특이해서, 평균 신장이 5명의 신장 자료를 대표하는 것 같지 않아요.\n교사: 그렇다면, 평균 말고 우리 농구팀 주전 선수들의 신장 자료를 대표하는 새로운 값을 생각해 볼까요?\n\n[이후에 농구팀의 신장 자료의 대푯값으로 중앙값 개념을 도입하는 교수·학습을 한다.]\n\n밑줄 친 ㉠의 자료는 평균이 대푯값으로 사용되기에 적절하지 않은 사례로서 수업에서 중앙값을 도입하기 위하여 제시된 것이다. 밑줄 친 ㉠의 자료로 적합한 '5명 신장의 예'를 제시하고, 예시한 자료의 특성을 설명하시오. 또한 2015 개정 수학과 교육과정(교육부 고시 제2020-236호)의 '교수·학습 방법'에서 수학적 문제 해결 능력으로서의 수학적 모델링 능력의 신장을 위해 강조한 사항을 쓰고, 이 강조 사항이 이 수업에서 어떻게 반영되고 있는지를 기술하시오. [4점]",
