      "answer": "밑줄 친 ㉠의 자료로 적합한 '5명 신장의 예'는, 168, 170, 172, 175, 205와 같이 4명은 서로 비슷한 신장을 가지고 있고 1명(센터 포지션 등)만 유독 큰 경우를 들 수 있다.\n\n예시한 자료의 특성은, 극단적으로 크거나 작은 값(이상치, outlier)이 하나 포함되어 있어, 평균을 구하면 그 극단값에 의해 평균이 크게 끌어올려져 나머지 4명의 신장 수준을 제대로 대표하지 못하게 된다는 것이다. 이 경우 평균보다 극단값의 영향을 덜 받는 중앙값이 5명의 신장 자료를 더 적절하게 대표할 수 있다.\n\n2015 개정 수학과 교육과정의 '교수·학습 방법'에서 수학적 모델링 능력의 신장을 위해 강조한 사항은, 실생활이나 다른 교과의 여러 현상에서 얻어지는 자료를 활용하여 수학적으로 해석하고 그 결과를 원래의 현상에 비추어 판단하는 경험을 학생에게 충분히 제공해야 한다는 것이다.\n\n이 강조 사항이 이 수업에서 반영되고 있는 방식은 다음과 같다. 교사는 추상적인 수치를 임의로 제시하는 대신, 우리 학교 농구팀 주전 선수 5명의 신장이라는 실제 맥락의 자료를 활용하고 있으며, 학생들이 이 자료의 특성(선수 구성의 특이성)을 실제 현상에 비추어 판단하며 평균이 부적합함을 스스로 깨닫고 새로운 대푯값(중앙값)의 필요성을 인식하도록 수업을 설계하고 있다. 이는 수학적 결과를 실제 현상과 연결지어 해석하는 수학적 모델링 능력 신장의 취지와 부합한다.",
