      "title": "수행평가 방법(포트폴리오·자기평가)의 명칭과 수학과 평가의 목적",
      "problem": "다음은 강 교사와 임 교사가 학기 초에 수학 교과의 평가 방법을 논의하면서 나눈 대화의 일부이다.\n\n강 교사: 이번 학기에는 ㉠학생이 일정 기간 동안 시험지, 단순 과제물, 프로젝트 형태의 결과물, 수학 일기 등을 모아 제출하고, 교사가 이 제출물에 기초하여 학생의 학습 내용·이해뿐만 아니라 관련된 교과 역량을 종합적으로 평가하면 좋을 것 같습니다.\n임 교사: 네. 학생과 협력하여 목표 영역을 정하고, 장시간에 걸친 학생들의 수학 학습 수행과 그 결과물을 정해진 준거에 따라 평가하고 활용하는 방법이군요.\n강 교사: 그렇습니다. 이 평가 방법을 지난 학기에 사용했을 때 학생이 제출한 예시 자료를 보여 드릴게요.\n\n[제목: OOO의 위대한 수학 산책 — 학년 초 진단평가, 다항식 단원 오답 노트, 함수 단원 모둠 활동지 모음, 컴퓨터로 배우는 수학(일차함수 그래프 그리기), 실생활 속 일차함수 프로젝트]\n\n임 교사: ㉡협력 학습 상황에서 동료의 역할 수행 정도나 집단 활동에 기여한 정도를 학생들이 서로 평가한 기록지를 제출물에 추가하면 좋겠어요.\n\n밑줄 친 ㉠, ㉡의 평가 방법의 명칭을 2015 개정 수학과 교육과정(교육부 고시 제2020-236호)의 '평가 방법'에 제시된 용어로 순서대로 쓰시오. 또한 2015 개정 수학과 교육과정의 '평가 원칙'에 제시된 수학과 평가의 목적을 기술하고, 그 목적의 관점에서 밑줄 친 ㉠의 평가 방법이 갖는 장점을 1가지 서술하시오. [4점]",
