      "answer": "밑줄 친 ㉠, ㉡의 평가 방법의 명칭은 순서대로 포트폴리오 평가, 동료평가이다.\n\n첫째, ㉠이 포트폴리오 평가인 이유는, 일정 기간 동안 시험지·과제물·프로젝트 결과물·수학 일기 등 다양한 자료를 누적하여 모으고 이를 종합적으로 평가한다는 점이 포트폴리오 평가의 정의와 정확히 일치하기 때문이다.\n둘째, ㉡이 동료평가인 이유는, 협력 학습 상황에서 동료의 역할 수행 정도나 기여도를 학생들이 서로 평가하는 것이 동료평가의 정의에 해당하기 때문이다.\n\n2015 개정 수학과 교육과정의 '평가 원칙'에 제시된 수학과 평가의 목적은, 교수·학습의 결과뿐만 아니라 과정에 대한 정보를 수집하여 학생 개개인의 수학 학습과 성장을 지원하고, 교사의 수업 개선에 활용하는 데 있다.\n\n이 목적의 관점에서 밑줄 친 ㉠(포트폴리오 평가)의 평가 방법이 갖는 장점은, 한 시점의 결과만이 아니라 학년 초 진단평가부터 이후의 오답 노트, 모둠 활동, 프로젝트에 이르기까지 장시간에 걸친 학습의 전 과정과 성장 추이를 누적된 자료를 통해 확인할 수 있다는 것이다. 이는 결과 중심의 일회성 평가로는 파악할 수 없는 학생의 학습 과정과 성장을 지원하려는 평가의 목적에 특히 잘 부합한다.",
