          "body": "㉠은 증명 분석을 통해 반례로부터 도출되는 숨은 보조정리를 원래 추측에 통합시켜 얻어진 개념으로, \"증명 생성적(proof-generated)\" 개념에 해당한다. ㉡은 수학이 자연과학처럼 잠정적이고 오류 가능한 지식이라는 라카토스의 관점으로, \"준경험적(quasi-empirical)\"이다."
