      "answer": "(가)의 박 교사가 밑줄 친 ㉠을 통해 평행사변형의 정의를 지도하는 방식을 지칭하는 용어는 국소적 조직화(local organization)이다.\n\n이 방식은 다음과 같이 설명할 수 있다. 처음부터 평행사변형의 정의를 완결된 형태로 제시하고 그로부터 성질들을 연역적으로 도출하는 전역적(공리적) 접근과 달리, 국소적 조직화는 학생이 먼저 비형식적으로 여러 성질을 탐구하여 발견하게 한 뒤, 그 발견된 성질들 사이의 논리적 관계(어떤 성질이 다른 성질을 함의하는지 등)를 점진적으로 탐구하게 함으로써, 학생 스스로 그 도형을 정의할 수 있는 최소한의 필요충분조건을 재구성해 나가도록 하는 방식이다.\n\n반 힐레의 기하 학습 수준 이론에서 (나)의 학생 1의 기하 학습 수준은 제2수준(분석, Analysis)이다.\n\n그렇게 판단한 근거는 다음과 같다. 학생 1은 평행사변형의 여러 성질(대변의 평행, 대변의 길이, 대각선의 이등분, 대각의 크기, 이웃한 내각의 합)을 정확히 나열할 수 있어, 도형을 구성하는 성질을 분석적으로 파악하는 제2수준의 특징을 보이고 있다. 그러나 \"두 쌍의 대변이 평행하다는 것과 대변의 길이가 같다는 것 사이에 관계가 없는 것 같다\"고 말하며 성질들 사이의 논리적 함의 관계를 파악하지 못하고 있는데, 이는 성질들 사이의 관계를 비형식적으로라도 논증할 수 있는 제3수준(비형식적 연역)에는 아직 도달하지 못했음을 보여주기 때문이다.",
