      "answer": "괄호 안의 ㉠에는 \"방정식이 이미 참이라고 가정하고, 그 가정으로부터 필연적으로 따르는 조건을 역으로 찾아 나가는 것으로 시작했습니다.\"가 적합하다. ㉡에는 \"삼각형에 내접하는 원이 이미 작도되었다고 가정하고, 그 원이 만족해야 할 조건을 역으로 찾아보는 것으로 시작하겠습니다.\"가 적합하다.\n\n분석법이 지니는 수학교육적 의의는, 학생이 문제 해결의 결과(결론)를 먼저 가정한 뒤 그로부터 필요한 조건을 거꾸로 추론해 나가는 발견적 사고 과정을 경험하게 함으로써, 정답을 이미 아는 상태에서 절차를 단순히 적용하는 것이 아니라 스스로 해결 방법 자체를 탐구하고 발견하는 능력을 기를 수 있다는 것이다.\n\n이를 뒷받침하는 근거를 이 수업에서 찾아보면, 예비교사는 \"내접원이 이미 작도되었다\"고 가정한 상태에서 출발하여, 원의 중심에서 각 변에 내린 수선의 길이가 같다는 것, 그리고 그로부터 삼각형이 세 개의 합동인 직각삼각형으로 나뉜다는 것을 차례로 추론해 나갔다. 이 과정에서 예비교사는 처음에는 전혀 몰랐던 작도법(각의 이등분선의 교점을 중심으로, 그 교점에서 변까지의 거리를 반지름으로 삼는 것)을 스스로 \"짐작\"해 낼 수 있었는데, 이는 결론을 먼저 가정하고 역으로 추론하는 분석법의 절차를 따랐기 때문에 가능했던 발견이라는 점에서 분석법의 교육적 의의를 뒷받침한다.",
