      "title": "프로이덴탈의 형식 불역의 원리 — 기하적·대수적 확장",
      "problem": "다음은 강 교수가 예비교사를 대상으로 형식 불역의 원리를 다루는 수업의 일부이다.\n\n강 교수: 지금까지 음수 지도를 형식적인 관점에서 접근하는 형식 불역의 원리를 설명했습니다. 그런데 프로이덴탈(H. Freudenthal)은 이를 '기하적·대수적 형식 불역의 원리'로 확장합니다. 여러분, 오른쪽과 같은 정수의 나눗셈을 어떻게 기하적인 방법으로 접근할 수 있을까요? [$2\\div2=1$, $1\\div2=\\dfrac{1}{2}$, $0\\div2=0$, $(-1)\\div2=?$, $(-2)\\div2=?$]\n예비교사A: 잘 모르겠어요.\n강 교수: 자, 주어진 나눗셈 식에서 나누는 수는 얼마인가요?\n예비교사A: 나누는 수는 2입니다.\n강 교수: 그렇습니다. 그럼 이 연산을 함수로 이해해 봅시다. 나누어지는 수 $x$에 연산 결과 $y$를 대응시킨다고 할 때, $y$는 얼마인가요?\n예비교사B: $x\\div2$, 즉 $\\dfrac{x}{2}$입니다.\n강 교수: 네, 맞습니다. 그런데 음수의 연산을 아직 배우지 않은 학생들이 할 수 있는 나눗셈 식은 어디까지인가요?\n예비교사A: $0\\div2=0$입니다.\n강 교수: 맞아요. 음수가 도입되기 전까지는 이 함수의 $x$의 범위가 $x\\geq0$으로 제한됩니다. 그런데 $x$의 범위를 음수까지 확장하면 다음과 같이 함수 $y=\\dfrac{x}{2}$의 그래프가 변화하게 됩니다.\n예비교사B: 결국 $x<0$일 때 $x\\div2$가 어떻게 정해져야 하는지 알 수 있는 거네요.\n강 교수: 그렇습니다. 예를 들어, 주어진 그래프에서 $x$좌표가 $-4$일 때의 $y$좌표를 구하면 나눗셈 식 ( ㉠ )을/를 유도할 수 있습니다.\n예비교사A: ㉡이렇게 음수의 나눗셈을 기하적인 방법으로 해석하다니 정말 창의적인 것 같습니다.\n강 교수: 맞아요. 일차함수의 그래프를 배운 후에 음수의 연산을 새로운 관점에서 보는 자료로 활용하면 좋을 것 같습니다.\n\n괄호 안의 ㉠에 들어갈 나눗셈 식을 쓰고, '기하적·대수적 형식 불역의 원리'의 의미를 위의 수업 장면과 관련지어 기하적 측면과 대수적 측면에서 설명하시오. 또한, 밑줄 친 ㉡에서 가장 두드러지게 나타나는 수학 교과 역량의 명칭을 2022 개정 수학과 교육과정에 제시된 용어로 쓰시오. [4점]",
