      "answer": "괄호 안의 ㉠에 들어갈 나눗셈 식은 $(-4)\\div2=-2$이다. 그래프 $y=\\dfrac{x}{2}$에서 $x=-4$일 때 $y=-2$이기 때문이다.\n\n'기하적·대수적 형식 불역의 원리'의 의미를 수업 장면과 관련지어 설명하면 다음과 같다. 기하적 측면에서 이 원리는, $x\\geq0$의 범위에서 그려진 그래프(직선의 일부)를 $x<0$의 범위까지 매끄럽게(끊김이나 꺾임 없이) 이어지는 하나의 직선으로 자연스럽게 연장함으로써, 그 연장된 직선 위의 점들이 나타내는 대응 관계로부터 음수의 나눗셈 결과를 자연스럽게 읽어낼 수 있다는 것이다. 대수적 측면에서 이 원리는, 양수 범위에서 성립하던 연산의 형식적 규칙($y=\\dfrac{x}{2}$라는 관계식)이 음수 범위로 확장되어도 형식적으로 동일하게 유지되도록 새로운 연산(음수의 나눗셈)을 정의한다는 것이다. 즉 기하적으로는 그래프의 연속적 연장으로, 대수적으로는 함수식의 형식적 불변으로 음수의 나눗셈을 정당화하고 있다.\n\n밑줄 친 ㉡에서 가장 두드러지게 나타나는 수학 교과 역량의 명칭은 창의·융합이다. 음수의 나눗셈이라는 대수적 개념을 그래프(기하적 표상)라는 다른 영역과 연결지어 새로운 관점에서 창의적으로 해석해 내고 있기 때문이다.",
