      "problem": "다음은 '수학평가론'의 강의 내용을 요약한 공책의 일부이다.\n\n<과제 1> 문제: 두 함수 $f(x)=\\log_{n}x$, $g(x)=1-\\log_{n}(x+4)$의 그래프가 구간 $1<x<2$에서 만나도록 하는 모든 $n$의 값의 합을 구하시오. (단, $n\\geq2$인 자연수이다.) [4점]\n\n[예시답안] 교점을 $(x,y)$라 하면, 방정식 $\\log_{n}x=1-\\log_{n}(x+4)$이므로 방정식 $x^{2}+4x-n=0$은 실근을 가진다. 이차함수의 그래프에 적용하면 직선 $x=-2$를 축으로 하는 포물선이므로, $1<x<2$에서 실근을 가지려면 $D\\geq0$, $f(1)>0$, $f(2)>0$이다. 따라서 $n\\geq-4$, $n<5$, $n<12$이므로, $n$의 값은 2, 3, 4이다. 합은 9이다.\n\n○ 우리가 만든 채점기준표\n채점기준표 A: 4점(적절한 방법을 사용하여 문제를 해결하고 답을 구함), 3점(문제는 해결했지만 단순한 계산 실수로 답을 구하지 못함), 2점(합리적으로 풀었지만 중요한 실수로 옳은 풀이를 방해함), 1점(문제를 이해한 듯하나 겨우 풀기 시작함), 0점(백지 혹은 오답 이외 다른 내용이 없음)\n\n채점기준표 B: 문제 이해(방정식을 이용하고 있음, 1점), 문제 해결(방정식 $x^{2}+4x-n=0$을 제시함 1점, 구간 $1<x<2$에서 해가 존재할 조건을 제시하고 모든 n의 값을 구함 1점), 답 구하기(모든 n의 값의 합을 정확히 구함 1점)\n\n[예시답안]의 채점 점수: 채점기준표 A에 의한 점수는 ( ㉠ )점이고, 채점기준표 B에 의한 점수는 ( ㉡ )점이다.\n\n<과제 2> 채점기준표 A에 의한 채점 방법과 비교하였을 때, 채점기준표 B에 의한 채점 방법이 가지는 장점 1가지를 적으시오.\n\n괄호 안의 ㉠과 ㉡에 들어갈 점수를 순서대로 쓰고, 괄호 안의 ㉡에 들어갈 점수를 부여한 이유를 채점기준표 B에 근거하여 설명하시오. 또한, <과제 2>에 대한 답을 적고, 장점의 이유를 채점기준표 B에 의한 채점 방법의 의미에 근거하여 서술하시오.",
