          "body": "[예시답안]에서 $f(2)>0$ 조건 계산이 $n<12$로 되어 있으나, 실제로는 $f(1)>0 \\Rightarrow 1+4-n>0 \\Rightarrow n<5$이고 $f(2)>0 \\Rightarrow 4+8-n>0 \\Rightarrow n<12$가 맞다. $D\\geq0 \\Rightarrow 16+4n\\geq0 \\Rightarrow n\\geq-4$(자연수이므로 자동충족). 세 조건 중 가장 강한 조건은 $n<5$이며 $n\\geq2$이므로 $n=2,3,4$, 합은 9로 예시답안 자체는 결과적으로 맞는 것으로 보임. 하지만 이 문제는 정답 정확성보다 채점 점수 부여가 핵심이므로, 두 기준표 모두 예시답안이 올바른 풀이 과정을 거쳐 정답에 도달했다고 보고 만점을 부여하는 것이 타당하다."
