      "answer": "괄호 안의 ㉠에 들어갈 점수는 4점이고, ㉡에 들어갈 점수는 3점이다.\n\n㉡에 3점을 부여한 이유를 채점기준표 B에 근거하여 설명하면 다음과 같다. [예시답안]은 문제 이해 항목(방정식을 이용하고 있음, 1점)을 충족하였고, 문제 해결 항목 중 방정식 $x^{2}+4x-n=0$을 제시한 부분(1점)은 충족하였다. 그러나 구간 $1<x<2$에서 해가 존재할 조건을 제시하고 모든 $n$의 값을 구하는 항목(1점)에서, $f(2)>0$ 조건으로부터 $n<12$를 도출하는 과정에 논리적 비약이나 표현상의 불완전함이 있다고 판단되면 이 항목은 인정받지 못할 수 있다. 답 구하기 항목(모든 $n$의 값의 합을 정확히 구함, 1점)은 충족하였으므로, 총 3점이 부여된다.\n\n<과제 2>에 대한 답은, 채점기준표 B에 의한 채점 방법은 학생이 문제 해결 과정에서 어느 세부 단계까지 도달했는지를 구체적으로 파악할 수 있다는 장점이 있다는 것이다.\n\n이 장점의 이유를 채점기준표 B에 의한 채점 방법의 의미에 근거하여 서술하면 다음과 같다. 채점기준표 A는 전체 풀이에 대해 하나의 총체적 점수만을 부여하므로, 학생이 어느 지점에서 실수하거나 이해가 부족했는지 세부적으로 파악하기 어렵다. 반면 채점기준표 B는 문제 이해, 문제 해결(세부 단계별), 답 구하기로 채점 영역을 세분화하여 각 단계별로 점수를 부여하므로, 학생의 강점과 약점이 어느 단계에 있는지 정확히 진단할 수 있어 이후 수업 개선이나 개별 지도에 훨씬 유용한 정보를 제공한다는 장점이 있다.",
