      "problem": "다음은 2022 개정 중학교 수학과 교육과정의 변화에 대한 두 교사의 대화이다. 괄호 안의 ㉠, ㉡에 해당하는 용어를 순서대로 쓰시오. [2점]\n\n정 교사: 2022 개정 중학교 수학과 교육과정에서 영역 명칭의 변화가 있네요.\n송 교사: 맞아요. 초등학교와 중학교의 연계성을 강화하기 위해서 초등학교와 통일하여 제시한 것으로 알고 있어요.\n정 교사: 네. 2015 개정 중학교 수학과 교육과정의 '문자와 식' 영역과 '함수' 영역을 통합하여 ( ㉠ ) 영역으로 제시한 거군요.\n송 교사: 그렇습니다. '확률과 통계' 영역도 '자료와 가능성' 영역으로 바뀌었어요.\n정 교사: 그럼 자료와 가능성 영역의 내용 체계(표)의 지식·이해 범주의 내용 요소 중, 2015 개정 중학교 수학과 교육과정의 확률과 통계 영역의 '내용 체계(표)의 내용 요소'와 비교해서 변화된 내용이 있을까요?\n송 교사: 네. 다음은 자료와 가능성 영역의 내용 체계(표)의 일부인데요. '상자그림'이 새롭게 추가된 것을 확인할 수 있는데요.\n\n[표: 지식·이해 범주, 중학교 1~3학년: ( ㉡ ), 도수분포표와 상대도수, 경우의 수와 확률, 산포도, 상자그림과 산점도]\n\n정 교사: 그렇군요. 내용 요소에 제시된 ( ㉡ ), 도수분포표, 상대도수, 확률, 산포도, 상자그림, 산점도는 자료와 가능성 영역의 '성취기준 적용 시 고려 사항'에 자료와 가능성 영역에서 다루는 용어로 제시되어 있습니다.",
