      "problem": "다음은 수학적 모델링과 수학화 과정에 대한 자료이다.\n\n(가) 현실적 문제 상황 [1단계]: 작은 소품 상자가 필요해서 문구점에서 한 변의 길이가 12cm인 정사각형 모양의 판지를 구입했다. 네 귀퉁이에서 같은 크기의 정사각형을 잘라내어, 남은 부분으로 뚜껑이 없는 최대 부피를 가지는 직육면체 모양의 소품 상자를 만드는 현실적 문제 상황을 탐구한다.\n\n(나) 미국수학교사협의회(NCTM)의 수학적 모델링 과정 — '(가)'를 [1단계]로 하는 '수학적 모델링' 과정의 설명과 예시. [2단계] 설명( ㉠ ) 예시( ㉡ ). [3단계] 설명: 수학적 분석을 실시한다. 예시: 직육면체의 밑면은 한 변의 길이가 $12-2x$인 정사각형이고, 높이가 $x$이므로 $V(x)=x(12-2x)^{2}$이다. $V'(x)=12(x-2)(x-6)$이므로 $0<x<6$에서 $V(x)$의 증가와 감소에 의해서 $x=2$에서 $V(x)$는 최대가 된다. [4단계] 설명: 현상에 맞도록 재해석하여 결론을 도출한다. 예시: 판지의 네 귀퉁이에서 잘라내는 정사각형의 한 변의 길이를 2cm로 하면, 상자의 최대 부피는 $128cm^{3}$이다.\n\n(다) 현실주의적 수학교육 이론의 수학화 과정 — '(가)'를 [1단계]로 하는 '수학화' 과정의 설명. [2단계]: 현실 내의 문제 상황을 형식적인 수학적 처리가 가능하도록 변환하는 과정이다. [3단계]: 세련된 좀 더 높은 수학적 처리가 가능하도록 하는 과정이다. [4단계]: 개념을 새로운 문제에 적용함으로써 개념을 강화하고 일반화하는 과정이다.\n\n'(가)'가 (나)와 (다)의 [1단계]가 될 수 있는 이유를, '수학적 모델링'과 '수학화'의 개념과 함께 서술하시오. 또한, (나)의 괄호 안의 ㉠과 ㉡에 들어갈 내용을 제시하시오. [4점]",
