      "problem": "(가)는 일차방정식 수업을 마친 후 학생 A가 쓴 자기성찰지의 일부이고, (나)는 강 교사가 학생 A를 관찰하고 작성한 수업일지의 일부이다. 괄호 안의 ㉠, ㉡에 해당하는 용어를 순서대로 쓰시오. [2점]\n\n(가) 오늘 수업 시간에 등식의 성질 '$a=b$이면, $a+c=b+c$'를 이용하여 일차방정식 $x-3=7$을 푸는 방법을 배웠다. 그런데 일차방정식은 $x$에 특정한 수를 넣어야 참이 되는데, 등식의 성질에서는 $c$에 어떤 수를 넣어도 참이 되는 이유가 궁금해졌다. 선생님이 해 주신 설명을 들었는데도 아직 잘 모르겠다. 그리고 선생님께서 일차방정식 $x-3=7$과 $y-3=7$의 해가 같은지를 질문하셨다. 나는 문자 $x$와 $y$가 달라서 당연히 이 두 방정식의 해가 다를 것이라고 대답했다. 선생님이 이 두 방정식의 해가 같은 이유를 설명해 주셨는데, 아직도 그 이유가 잘 이해되지 않는다.\n\n(나) 학생 A는 등식의 성질에서 사용된 문자 $c$가 특정한 수를 나타내는 것이 아니라 임의의 수를 나타낸다는 것을 이해하지 못하는 것으로 보인다. 또한 방정식에서 문자가 바뀌면 방정식의 해도 바뀐다고 생각하고 있는데, 방정식에서 문자를 임의로 선택할 수 있다는 것을 이해하지 못하는 것으로 파악된다. 이상에서 학생 A는 ( ㉠ ) 개념에 대한 인지장애를 가지고 있는 것으로 보인다. ( ㉠ )은/는 주로 문자로 표현되며 다양한 측면을 가지고 있다. 그중에 $x-3=7$에서와 같이 방정식의 해를 나타내는 $x$는 자리지기로서의 ( ㉡ )(으)로 사용된 경우이고, 등식의 성질 '$a=b$이면, $a+c=b+c$'에 쓰인 문자 $a, b, c$는 일반화의 표현을 위해 사용된 경우이다. 앞으로 학생 A에게 방정식의 문자 $x$가 나타내는 ( ㉡ ) 개념과 이를 포괄하는 ( ㉠ ) 개념을 최대한 쉽게 설명해 주는 기회를 마련해야겠다.",
