      "problem": "(가)~(라)는 수학적 지식에 대한 여러 수리철학의 관점을 설명한 것이다. 밑줄 친 ㉠~㉣ 중 옳지 않은 것 2가지를 찾아 바르게 고쳐 쓰시오. [2점]\n\n(가) ㉠플라톤주의(Platonism)에 따르면, 수학의 대상인 수나 도형은 불변의 이데아로 간주된다. 수학적 지식은 완전한 대상에 대한 지식이므로 확실한 지식이다.\n\n(나) ㉡직관주의는 수학적 지식이 참임이 입증된 것이 아니라 반증 가능한 것이며 반증되기 전까지는 잠정적으로 참이라고 본다. 증명과 반박의 논리에 의해 수학적 지식은 성장한다.\n\n(다) ㉢형식주의에서 지식은 자주적 구성의 원리, 생장 지향성의 원리, 비객관성의 원리를 따른다. 수학적 지식의 확실성은 수학적 지식의 적합성과 적응성으로 대치된다.\n\n(라) ㉣사회적 구성주의에서 객관성은 사회적 합의의 가능성을 의미한다. 개인의 주관적인 수학적 지식은 공표되어 사회 속에서 공적인 비판과 재구성을 거쳐 객관적인 수학적 지식이 된다.",
