      "answer": "옳지 않은 것은 ㉡과 ㉢이다.\n\n첫째, ㉡은 직관주의가 아니라 라카토스의 오류주의(준경험주의, fallibilism)로 고쳐야 한다. 수학적 지식이 반증 가능하고 잠정적으로 참이며 증명과 반박을 통해 성장한다는 설명은 직관주의(브라우어, 배중률 거부와 구성적 증명 강조)의 정의가 아니라 라카토스가 제시한 오류주의의 핵심 내용이기 때문이다.\n둘째, ㉢은 형식주의가 아니라 급진적 구성주의로 고쳐야 한다. 지식의 자주적 구성, 생장 지향성, 비객관성의 원리, 그리고 확실성 대신 적합성·적응성을 강조하는 것은 형식주의(힐베르트, 공리 체계 내 기호 조작)의 정의가 아니라 폰 글라저스펠드가 제시한 급진적 구성주의의 핵심 내용이기 때문이다.",
