      "title": "통계 프로젝트 활동 — 그래프 유형 피드백과 투키의 그래프 현시성",
      "problem": "다음은 류 교사가 진행한 중학교 '자료와 가능성' 영역의 수업에서 두 모둠이 수행한 통계 프로젝트 활동 과정을 공유한 자료이다. 최종 산출물을 만들기 전에 류 교사는 각 모둠에 피드백을 제공하려고 한다.\n\nA 모둠: 탐구 주제: 학교 도서관 이용 실태. 자료 수집: 1학년과 3학년 학생을 대상으로 일주일간 학교 도서관 방문 일수를 입력하는 온라인 설문 조사. 수집한 자료는 총 120명(1학년 60명, 3학년 60명). 현재까지 진행된 과정: 자료를 정리해서 표로 나타내 보았다. 두 집단의 분포와 특성을 비교하기 위해 그래프를 그릴 예정인데, 두 집단 간의 분포와 특성, 평균과 중앙값 등을 한눈에 볼 수 있는 ㉠그래프는 어떤 것이 있을지 선생님의 피드백을 받고 싶다.\n\nB 모둠: 탐구 주제: 우리 지역 청소년 수영 기록 분석. 자료 수집: 지난 10년간 우리 지역 청소년 남자 50m 자유형 1등 기록. 현재까지 진행된 과정: 자료를 표로 정리하고 그래프를 나타내 보았다(꺾은선그래프, 기록이 30.64초에서 28.80초로 완만히 감소하는 추세). 지역 뉴스에서는 지난 10년간 기록이 상당히 단축되었다고 했는데, 우리 모둠은 ㉡그래프에서 큰 변화를 발견하지 못해서 선생님께 피드백을 받고 싶다.\n\n<작성 방법>\n◦ 2022 개정 수학과 교육과정(교육부 고시 제2022-33호)의 '자료와 가능성' 영역에서 추가된 '성취기준'에 근거하여, A 모둠 활동 자료의 밑줄 친 ㉠에 대하여 교사가 제시할 그래프의 유형을 쓰고 그 특징을 서술할 것.\n◦ B 모둠 활동 자료의 밑줄 친 ㉡의 이유를 투키(J. Tukey)의 '그래프의 현시성'에 근거하여 서술하고, 이에 대하여 교사가 제공할 수 있는 적절한 피드백 1가지를 제시할 것.",
