      "problem": "(가)는 예비 교사가 웹 기반 소프트웨어를 활용하여 원의 접선에 관한 성질을 지도하는 수업의 일부이며, (나)는 지도 교사가 예비 교사의 수업을 참관하고 작성한 수업 참관 평가표의 일부이다.\n\n(가) 예비 교사: 원 O 밖의 한 점 P에서 원 O에 그은 두 접선의 접점을 각각 A, B라 하고, 점 P를 움직이면서 선분 PA와 선분 PB의 길이를 관찰해 봅시다. 무엇을 발견했나요?\n학생 A: 두 선분의 길이가 같아 보입니다.\n예비 교사: 그럼 이 소프트웨어의 측정 기능을 사용하여 선분 PA와 선분 PB의 길이의 측정값을 비교해 봅시다.\n학생 B: 정말 두 선분의 길이가 같습니다.\n예비 교사: 잘했습니다. 이어지는 조작 활동으로 어떤 활동을 하면 좋을까요?\n학생 C: ( ㉠ )?\n예비 교사: 옳은 생각입니다. 이번에도 선분 PA와 선분 PB의 길이가 같은지 확인해 보세요.\n학생 A: 두 선분의 길이는 항상 같아요.\n예비 교사: 지금까지 발견한 내용을 누가 정리해 볼까요?\n학생 B: 원 밖의 한 점에서 그 원에 그은 두 접선의 길이인 선분 PA와 선분 PB의 길이는 같습니다.\n예비 교사: 네, 좋습니다. 공학 도구를 활용하여 발견한 원의 접선의 성질을 이제 증명해 봅시다.\n\n(나) 수업 참관 평가표 — 평가 항목: ① 도형의 성질을 정당화하는 다양한 방법을 활용하였는가? (우수) ② 수학과 수업의 교수·학습 방안 중 적절한 유형을 선택하여 적용하였는가? (우수)\n\n<작성 방법>\n◦ 딘즈(Z. Dienes)의 수학적 다양성의 원리를 적용한 조작 활동이 되도록 괄호 안의 ㉠에 들어갈 내용을 쓸 것.\n◦ (가)와 2022 개정 수학과 교육과정의 '성취기준 적용 시 고려 사항'에 근거하여, 지도 교사가 (나)의 평가 항목 ①을 '우수'로 평가한 이유를 서술할 것.\n◦ (가)와 2022 개정 수학과 교육과정의 '교수·학습 방안' 중 교수·학습 방안에 근거하여, 지도 교사가 (나)의 평가 항목 ②를 '우수'로 평가한 이유가 되는 교수·학습 방안의 유형을 쓰고 그 특징을 설명할 것.",
