      "answer": "딘즈의 수학적 다양성의 원리를 적용한 조작 활동이 되도록 괄호 안의 ㉠에 들어갈 내용은, \"원 O의 크기를 다르게 바꾸거나 점 P의 위치를 다른 곳으로 옮겨서, 다시 두 접선을 그어보는 건 어떨까요\"이다. 원의 크기와 점 P의 위치라는 비본질적 조건을 다양하게 바꾸어 보면서도 \"두 접선의 길이가 같다\"는 본질적 성질이 계속 유지되는지 확인해야, 그 성질이 특정 상황에 국한된 우연이 아니라 일반적으로 성립하는 성질임을 파악할 수 있기 때문이다.\n\n지도 교사가 (나)의 평가 항목 ①을 '우수'로 평가한 이유는 다음과 같다. 예비 교사는 (가)에서 공학 도구(웹 기반 소프트웨어)의 측정 기능을 이용하여 두 접선의 길이가 같음을 경험적으로 확인하는 활동을 먼저 진행한 뒤, 이어서 그 성질을 연역적으로 증명하는 단계로 나아가고 있다. 이는 경험적(귀납적) 정당화와 연역적 정당화라는 서로 다른 정당화 방법을 모두 활용하여 도형의 성질을 다각도로 정당화하도록 지도한 것이므로, 성취기준 적용 시 고려 사항에서 요구하는 다양한 정당화 방법의 활용이 잘 이루어졌다고 볼 수 있기 때문이다.\n\n지도 교사가 (나)의 평가 항목 ②를 '우수'로 평가한 이유가 되는 교수·학습 방안의 유형은 탐구 학습(발견 학습)이다.\n\n그 특징은, 교사가 결론을 직접 제시하지 않고 학생들이 공학 도구를 활용해 스스로 조작하고 관찰하며 원의 접선에 관한 성질을 발견하도록 안내한다는 것이다. 학생이 능동적으로 탐구 활동에 참여하여 스스로 수학적 성질을 발견하게 함으로써, 지식을 수동적으로 전달받는 것보다 더 깊이 있는 이해와 학습 동기를 이끌어낼 수 있다는 것이 탐구 학습(발견 학습)의 핵심 특징이기 때문이다.",
