      "title": "쉐발라드의 지식의 파손성과 브루소의 극단적 교수 현상 용어",
      "problem": "다음은 '수학교육론' 수업에서 쉐발라드(Y. Chevallard)와 브루소(G. Brousseau)의 이론을 다룬 수업 자료의 일부이다. 괄호 안의 ㉠과 ㉡에 해당하는 용어를 순서대로 쓰시오. [2점]\n\n○ 쉐발라드(Y. Chevallard)는 교사가 교육적 의도를 가지고 학문적 지식을 가르칠 지식으로 변환하는 것을 지식의 ( ㉠ )(이)라고 하였다. 그는 교육 현상을 올바르게 이해하려면 '교사-학생'의 이원적 관계가 아니라, '교사-지식-학생'의 삼원적 관계로 바라볼 필요가 있다고 보았다. 교사는 이미 알고 있는 지식을 학생들에게 전달하기 위한 목적으로 다시 다루는 것이지만, 학생은 알지 못하는 지식을 처음 접하게 된다. 따라서 지식을 변형하는 주체인 교사, 변형된 지식을 대하는 주체인 학생과 더불어 지식을 고려할 필요가 있다.\n\n○ 브루소(G. Brousseau)는 교사가 학생들이 수학 지식을 의미 있게 학습할 수 있게 하려면 지식을 개인화/배경화하고 탈개인화/탈배경화하는 과정을 균형 있게 다루어야 한다고 보았다. 이 과정이 적절하게 이루어지지 않으면 여러 가지 극단적인 교수 현상이 나타날 수 있다. 한 예로 학생의 개인화/배경화 과정이 지나치게 강조되면, 교사가 가르치고자 한 수학 지식 자체로부터 학생의 개인화/배경화 과정을 용이하게 하기 위해 도입한 교수학적 보조 수단으로 학생들의 사고가 옮겨가는 ( ㉡ )이/가 일어날 수 있다.",
