      "title": "폴리아의 문제해결 교육론 — 방법적 지식과 발문 단계",
      "problem": "다음은 '수학교육론' 수업에서 폴리아(G. Polya)의 문제해결 교육론을 다룬 수업 자료의 일부이다. 괄호 안의 ㉠에 들어갈 용어를 쓰고, 폴리아(G. Polya)의 문제해결 과정의 네 단계 중 밑줄 친 ㉡과 같은 발문을 제시하는 단계의 명칭을 쓰시오. [2점]\n\n○ 폴리아(G. Polya)는 문제해결 교육의 중요성을 강조하면서, 문제해결 교육의 핵심은 방법적 지식인 수학적 ( ㉠ )을/를 터득하는 데 있다고 보았다. 이때 ( ㉠ )(이)란 문제해결에서 전형적으로 유용한 발견과 발명의 방법과 규칙, 문제해결 전략과 전술을 말한다. 문제해결 과정의 네 단계에서 교사가 하는 발문과 권고는 효과적인 사고 활동을 유발해서 학생들의 문제해결을 도울 수 있다.\n\n○ 다음은 교사와 학생들이 가로의 길이가 $a$, 세로의 길이가 $b$, 높이가 $c$인 직육면체의 대각선의 길이를 구하는 문제를 해결하면서 나눈 대화이다.\n\n교사: 미지의 것은 무엇입니까?\n학생1: 직육면체의 대각선의 길이입니다. 미지의 것은 $x$로 나타내었습니다.\n교사: $a, b, c$와 $x$를 연결하는 조건은 무엇입니까?\n학생2: $x$가 가로의 길이, 세로의 길이, 높이가 각각 $a, b, c$인 직육면체의 대각선의 길이가 된다는 것입니다.\n교사: ㉡미지의 것이 유사한 다른 문제를 알고 있나요?\n학생3: 예전에 직각삼각형의 한 변의 길이를 구하는 문제를 풀어본 적이 있습니다.\n교사: 여러분이 기억해 낸 문제는 직각삼각형에 관한 것이군요. 위 그림에서 직각삼각형을 찾아보세요.\n학생1: 아! 미지의 것이 직각삼각형의 빗변의 길이였군요. 피타고라스 정리를 사용하면 구할 수 있겠어요.",
