      "answer": "괄호 안의 ㉠에 들어갈 용어는 발견술(heuristic)이다.\n\n밑줄 친 ㉡과 같은 발문을 제시하는 단계의 명칭은 계획 수립 단계이다.\n\n첫째, ㉠이 발견술인 이유는, 문제해결에서 전형적으로 유용한 발견과 발명의 방법·규칙·전략·전술을 폴리아가 발견술이라 불렀기 때문이다.\n둘째, ㉡이 계획 수립 단계에 해당하는 이유는, \"미지의 것이 유사한 다른 문제를 알고 있는가\"라는 질문이 이전에 해결한 유사 문제를 떠올려 현재 문제의 해결 계획을 세우도록 유도하는 대표적인 발견술적 질문으로, 폴리아의 문제해결 4단계(이해-계획 수립-실행-반성) 중 계획 수립 단계에서 제시되는 전형적인 발문이기 때문이다.",
