          "body": "프로이덴탈의 교수학적 현상학은 개념이 어떤 현상을 조직하기 위해 발생했는지 분석하여, 학생에게도 그 현상을 제시함으로써 개념 형성을 유도하는 접근이다. 이 수업에서는 \"수 계수 이차방정식을 반복해서 푸는 현상\"이 \"일반화된 문자 계수 공식\"이라는 개념을 조직하는 현상으로 제시되고 있다."
