          "body": "㉠은 현실 문제를 수학화하고 그 결과를 현실에 적용해 해석하는 과정, 즉 수학적 모델링이다. ㉡은 근접발달영역 내 도움 제공을 뜻하는 비계설정(scaffolding)이다."
